 \textcolor{blue}{\href{http://shop.ieee.org/}{http://shop.ieee.org/}}. An IEEE Account is required for access to the dictionary,\linebreak
 \hspace*{-6.36pt}and one can be created at no charge on the dictionary sign-in page.%
 }
 \draw[blue,line width=0.36pt] (270.18,695.04)--(334.15,695.04);

 \HLAFixedBlock{90}{704.10}{6}{\rmfamily\raggedright}{6.36}{7}{12}
 \HLAFixedBlock{96.36}{707.25}{425.64}{\rmfamily\raggedright}{7.98}{9.4}{%
 Notes in text, tables, and figures are given for information only and do not contain requirements needed to implement the standard.%
