\HLASourcePage{26}{25}
\thispagestyle{hla-body}
\begin{hlafixedpage}
 \HLADefinitionAt{69.79}{%
 \HLADefinitionAnchor{delete}\HLADefinitionTerm{delete}: To invoke the \emph{Delete Object Instance} service to eliminate a particular object instance. \emph{See also}:\linebreak
 \textbf{remove}.%
 }

 \HLADefinitionNoteAt{90}{105.98}{NOTE---See 6.16.}

 \HLADefinitionAt{127.81}{%
 \HLADefinitionAnchor{designator}\HLADefinitionTerm{designator}: A generic view of arguments referenced in service descriptions. This view improves clarity in\linebreak
 situations when arguments (mostly identifiers) to services have different views (implementations) due to a\linebreak
 particular programming language or application programmer's interface (API).%
 }

 \HLADefinitionAt{175.81}{%
 \HLADefinitionAnchor{dimension}\HLADefinitionTerm{dimension}: A named interval. The interval is defined by an ordered pair of values, the first being the\linebreak
 dimension lower bound and the second being the dimension upper bound. A runtime infrastructure (RTI)\linebreak
 provides a predefined interval, whose lower and upper bounds are fixed as [0, the dimension's upper bound)\linebreak
 as specified in the federation object model (FOM) Document Data (FDD). This interval provides a single\linebreak
 basis for communication of all dimension-related data with an RTI. All normalized intervals communicated\linebreak
 to the RTI will be subsets of this interval.%
 }

 \HLADefinitionNoteAt{90}{260.00}{NOTE---See 9.1.}

 \HLADefinitionAt{281.77}{%
 \HLADefinitionAnchor{directed-interaction}\HLADefinitionTerm{directed interaction}: An explicit action taken by a federate directed to a specific object instance that may\linebreak
 have some effect or impact on another federate within a federation execution that owns attributes of that\linebreak
 object instance.%
 }

 \HLADefinitionAt{329.76}{%
 \HLADefinitionAnchor{directed-interaction-class}\HLADefinitionTerm{directed interaction class}: An association between an interaction class and an object class where instances\linebreak
 of the interaction class may be directed to be received by interested federate that owns attribute instances of\linebreak
 the object class.%
 }

 \HLADefinitionAt{375.57}{%
 \HLADefinitionAnchor{discover}\HLADefinitionTerm{discover}: To receive an invocation of the \emph{Discover Object Instance} \textdagger{}\HLASupMark{13} service for a particular object\linebreak
 instance.%
 }

 \HLADefinitionNoteAt{90}{413.96}{NOTE---See 6.9.}

 \HLADefinitionAt{435.79}{%
 \HLADefinitionAnchor{discovered-class}\HLADefinitionTerm{discovered class}: The class that was an object instance's candidate discovery class at a joined federate when\linebreak
 that object instance was discovered by that joined federate. \emph{See also}: \textbf{candidate discovery class}.%
 }

 \HLADefinitionNoteAt{90}{471.98}{NOTE---See 5.1.2.}

 \HLADefinitionAt{493.81}{%
 \HLADefinitionAnchor{dynamic-link-compatibility}\HLADefinitionTerm{dynamic link compatibility (DLC)}: The ability to interchange the implementation of an API with another\linebreak
 without having to recompile or relink the application software that uses the API.%
 }

 \HLADefinitionAt{529.81}{%
 \HLADefinitionAnchor{epsilon-time-interval}\HLADefinitionTerm{epsilon time interval}: The distance between any two consecutive logical times T1 and T2 (i.e. the set of\linebreak
 logical times between T1 and T2 is empty). For some representations of local time (e.g. floating point), the\linebreak
 distance may not be the same for all such instances of T1 and T2.%
 }

 \HLADefinitionAt{577.80}{%
 \HLADefinitionAnchor{exception}\HLADefinitionTerm{exception}: Notification of any irregularity that may occur during a service invocation.%
 }

 \HLADefinitionAt{601.80}{%
 \HLADefinitionAnchor{fault}\HLADefinitionTerm{fault}: The occurrence of an unexpected event, at any point during a federation execution, that prevents one\linebreak
 or more joined federates in the federation from executing in an HLA-compliant manner.%
 }

 \HLADefinitionAt{637.80}{%
 \HLADefinitionAnchor{federate}\HLADefinitionTerm{federate}: An application that may be or is currently coupled with other software applications under a\linebreak
 federation object model (FOM) Document Data (FDD) and a runtime infrastructure (RTI). \emph{See also}:\linebreak
 \textbf{federate application}; \textbf{joined federate}.%
 }

 \draw[line width=0.48pt] (90.78,701.90)--(127.26,701.90);
 \HLAFixedBlock{90}{704.10}{6}{\rmfamily\raggedright}{6.36}{7}{13}
 \HLAFixedBlock{96.36}{707.25}{425.64}{\rmfamily\raggedright}{7.98}{9.4}{%
 All RTI-initiated services are denoted with a \textdagger{} (printer's dagger) after the service name.%
 }
\end{hlafixedpage}
\clearpage

\HLASourcePage{28}{27}
\thispagestyle{hla-body}
\begin{hlafixedpage}
 \HLADefinitionAt{69.79}{%
 \HLADefinitionAnchor{inherited-directed-interaction-class}\HLADefinitionTerm{inherited directed interaction class}: A directed interaction class of an object class that was declared in a\linebreak
 superclass of that object class in the object class hierarchy tree defined in the federation object model\linebreak
 (FOM).%
 }

 \HLADefinitionAt{117.78}{%
 \HLADefinitionAnchor{inherited-parameter}\HLADefinitionTerm{inherited parameter}: An interaction parameter that was declared in a superclass of that interaction class in\linebreak
 the interaction class hierarchy tree defined in the federation object model (FOM).%
 }

 \HLADefinitionAt{153.78}{%
 \HLADefinitionAnchor{initial-time-value}\HLADefinitionTerm{initial time value}: The point on the time axis for which no other point occurs before it.%
 }

 \HLADefinitionAt{177.78}{%
 \HLADefinitionAnchor{in-scope}\HLADefinitionTerm{in scope}: Of or pertaining to an instance attribute of an object instance for which all of the following apply:%
 }

 \HLAFixedAlphaList{100.02}{201.78}{421.98}{0}{%
 \item The object instance is known to the joined federate.
 \item The instance attribute is owned by another joined federate.
 \item The instance attribute's corresponding class attribute is one of the following:
 }

 \HLAFixedBlock{121.98}{240.78}{8.4}{\rmfamily\raggedright}{9.96}{12}{1)}
 \HLAFixedBlock{142.03}{240.78}{379.97}{\rmfamily}{9.96}{12}{%
 A subscribed attribute of the known class of the object instance, or%
 }
 \HLAFixedBlock{121.98}{255.78}{8.4}{\rmfamily\raggedright}{9.96}{12}{2)}
 \HLAFixedBlock{142.04}{255.78}{379.96}{\rmfamily}{9.96}{12}{%
 A subscribed attribute of the known class of the object instance with regions, and the update\linebreak
 region set of the instance attribute at the owning joined federate overlaps the subscription\linebreak
 region set of the instance attribute's corresponding class attribute at the known class of the\linebreak
 instance attribute at the subscribing joined federate.%
 }
 \HLADefinitionNoteAt{142.02}{309.98}{NOTE---See 6.1.}

 \HLADefinitionAt{331.81}{%
 \HLADefinitionAnchor{instance-attribute}\HLADefinitionTerm{instance attribute}: A named characteristic of an object instance denoted by a pair composed of the object\linebreak
 instance designator and the attribute designator.%
 }

 \HLADefinitionAt{367.81}{%
 \HLADefinitionAnchor{interaction}\HLADefinitionTerm{interaction}: An explicit action taken by a federate that may have some effect or impact on another federate\linebreak
 within a federation execution.%
 }

 \HLADefinitionAt{403.80}{%
 \HLADefinitionAnchor{interaction-class}\HLADefinitionTerm{interaction class}: A template for a set of characteristics that is common to a group of interactions. These\linebreak
 characteristics correspond to the parameters that individual federates may associate with interactions.%
 }

 \HLADefinitionAt{439.80}{%
 \HLADefinitionAnchor{interaction-parameters}\HLADefinitionTerm{interaction parameters}: The information associated with an interaction that a federate potentially affected\linebreak
 by the interaction may receive to calculate the effects of that interaction on its current state.%
 }

 \HLADefinitionAt{475.80}{%
 \HLADefinitionAnchor{joined-federate}\HLADefinitionTerm{joined federate}: A member of a federation execution, actualized by a federate application invoking the \emph{Join}\linebreak
 \emph{Federation Execution} service as prescribed in IEEE Std 1516.1\texttrademark-2025. \emph{See also}: \textbf{federate application}.%
 }

 \HLADefinitionAt{511.80}{%
 \HLADefinitionAnchor{known-class}\HLADefinitionTerm{known class}:%
 }

 \HLAFixedAlphaList{100.02}{535.80}{421.98}{0}{%
 \item An object instance's registered class if the joined federate knows about the object instance as a result\linebreak
 of having registered it, or
 \item An object instance's discovered class if the joined federate knows about the object instance as a\linebreak
 result of having discovered it.
 }

 \HLADefinitionAt{595.80}{%
 \HLADefinitionAnchor{known-object-instance}\HLADefinitionTerm{known object instance}: An object instance that a given joined federate has either registered or discovered\linebreak
 and that the joined federate has not subsequently deleted (globally or locally) or been notified to remove. \emph{See}\linebreak
 \emph{also}: \textbf{register}; \textbf{discover}; \textbf{delete}; \textbf{local delete}; \textbf{remove}.%
 }

 \HLADefinitionAt{643.80}{%
 \HLADefinitionAnchor{last-known-time-position}\HLADefinitionTerm{last known time position}: The last time position to which a lost joined federate was successfully granted, as\linebreak
 seen from the remaining federation execution.%
 }

 \HLADefinitionAt{679.80}{%
 \HLADefinitionAnchor{local-delete}\HLADefinitionTerm{local delete}: To invoke the \emph{Local Delete Object Instance} service to inform the runtime infrastructure (RTI)\linebreak
 that it is to treat the specified object instance as if the RTI had never notified the joined federate to discover%
 }
\end{hlafixedpage}
\clearpage

\HLASourcePage{30}{29}
\thispagestyle{hla-body}
\begin{hlafixedpage}
 \HLADefinitionAt{69.79}{%
 \HLADefinitionAnchor{object-model-framework}\HLADefinitionTerm{object model framework}: The rules and terminology used to describe High Level Architecture (HLA)\linebreak
 object models.%
 }

 \HLADefinitionAt{103.81}{%
 \HLADefinitionAnchor{optimistic-logical-time}\HLADefinitionTerm{optimistic logical time (OLT)}: A supplementary logical time that facilitates optimistic time advancement.\linebreak
 The optimistic logical time is provided, along with the update to the federate's logical time, in a \emph{Flush Queue}\linebreak
 \emph{Grant \textdagger{}} service call as a response to a \emph{Flush Queue Request} service call. It is the minimum of the time\linebreak
 supplied in the \emph{Flush Queue Request} and the timestamps of any TSO messages delivered in response to that\linebreak
 \emph{Flush Queue Request}. The optimistic logical time indicates a lower bound on the next logical time the\linebreak
 federate could be advanced to if no TSO messages with a timestamp less than it are received in the future.%
 }

 \HLADefinitionAt{187.80}{%
 \HLADefinitionAnchor{optimistic-lookahead}\HLADefinitionTerm{optimistic lookahead}: The lookahead the federate would have if actually granted to the optimistic logical\linebreak
 time.%
 }

 \HLADefinitionAt{223.80}{%
 \HLADefinitionAnchor{order-type}\HLADefinitionTerm{order type}: A runtime infrastructure (RTI) means of ordering messages originating from multiple joined\linebreak
 federates that are delivered to a single joined federate. Different categories of service are defined with\linebreak
 different characteristics regarding whether and how an RTI orders messages that are to be delivered to a\linebreak
 joined federate.%
 }

 \HLADefinitionAt{281.76}{%
 \HLADefinitionAnchor{out-of-scope}\HLADefinitionTerm{out of scope}: Of or pertaining to an instance attribute of an object instance for which one or more of the\linebreak
 following are not true:%
 }

 \HLAFixedAlphaList{100.02}{315.78}{421.98}{0}{%
 \item The object instance is known to the joined federate.
 \item The instance attribute is owned by another joined federate.
 \item The instance attribute's corresponding class attribute is one of the following:
 }

 \HLAFixedBlock{121.98}{354.78}{8.4}{\rmfamily\raggedright}{9.96}{12}{1)}
 \HLAFixedBlock{142.03}{354.78}{379.97}{\rmfamily}{9.96}{12}{%
 A subscribed attribute of the known class of the object instance, or%
 }
 \HLAFixedBlock{121.98}{369.78}{8.4}{\rmfamily\raggedright}{9.96}{12}{2)}
 \HLAFixedBlock{142.04}{369.78}{379.96}{\rmfamily}{9.96}{12}{%
 A subscribed attribute of the known class of the object instance with regions, and the update\linebreak
 region set of the instance attribute at the owning joined federate overlaps the subscription\linebreak
 region set of the instance attribute's corresponding class attribute at the known class of the\linebreak
 instance attribute at the subscribing joined federate.%
 }
 \HLADefinitionNoteAt{142.02}{423.98}{NOTE---See 6.1.}

 \HLADefinitionAt{443.77}{%
 \HLADefinitionAnchor{overlap}\HLADefinitionTerm{overlap}:%
 }

 \HLAFixedBlock{100.02}{465.79}{8.4}{\rmfamily\raggedright}{9.96}{12}{a)}
 \HLAFixedBlock{121.98}{465.79}{400.02}{\rmfamily}{9.96}{12}{%
 Pertaining to region sets: given two region sets, to have a region in each set such that the two regions\linebreak
 overlap.%
 }
 \HLAFixedBlock{100.02}{487.80}{8.4}{\rmfamily\raggedright}{9.96}{12}{b)}
 \HLAFixedBlock{121.98}{487.80}{400.02}{\rmfamily}{9.96}{12}{%
 Pertaining to regions: given two regions, to have at least one dimension in common if and only if,\linebreak
 for each dimension the regions have in common, their respective ranges in the common dimension\linebreak
 overlap. If two regions do not have any dimensions in common, the regions do not overlap.%
 }
 \HLAFixedBlock{100.02}{523.80}{8.4}{\rmfamily\raggedright}{9.96}{12}{c)}
 \HLAFixedBlock{121.97}{523.80}{400.03}{\rmfamily}{9.96}{12}{%
 Pertaining to ranges: given two ranges (A = [\emph{a}\textsubscript{lower}, \emph{a}\textsubscript{upper}) and B = [\emph{b}\textsubscript{lower}, \emph{b}\textsubscript{upper})), to overlap if and\linebreak
 only if%
 }

 \HLAFixedBlock{121.98}{555.79}{8.4}{\rmfamily\raggedright}{9.96}{12}{1)}
 \HLAFixedBlock{142.02}{555.79}{379.98}{\rmfamily}{9.96}{12}{%
 Either \emph{a}\textsubscript{lower} = \emph{b}\textsubscript{lower} or (\emph{a}\textsubscript{lower} $<$ \emph{b}\textsubscript{upper} and \emph{b}\textsubscript{lower} $<$ \emph{a}\textsubscript{upper}) or%
 }
 \HLAFixedBlock{121.98}{570.79}{8.4}{\rmfamily\raggedright}{9.96}{12}{2)}
 \HLAFixedBlock{142.02}{570.79}{379.98}{\rmfamily}{9.96}{12}{%
 The Allow Relaxed DDM switch is enabled and the RTI implementation makes the\linebreak
 determination, based on implementation-specific criteria, that the ranges are sufficiently close\linebreak
 to warrant an expanded interpretation of one or both ranges; neither range may ever be reduced.%
 }
 \HLADefinitionNoteAt{121.98}{612.98}{NOTE---See 9.1.}

 \HLADefinitionAt{634.81}{%
 \HLADefinitionAnchor{owned}\HLADefinitionTerm{owned}: Pertaining to the relationship between an instance attribute and a joined federate: when the joined\linebreak
 federate has the unique right to update the instance attribute's value.%
 }

 \HLADefinitionAt{670.81}{%
 \HLADefinitionAnchor{owned-instance-attribute}\HLADefinitionTerm{owned instance attribute}: An instance attribute that is explicitly modeled by the owning joined federate. A\linebreak
 joined federate that owns an instance attribute has the unique responsibility to provide values for that\linebreak
 instance attribute to the federation, through the runtime infrastructure (RTI), as documented in the federation\linebreak
 object model (FOM) Document Data (FDD).%
 }
\end{hlafixedpage}
\clearpage

\HLASourcePage{31}{30}
\thispagestyle{hla-body}
\begin{hlafixedpage}
 \HLADefinitionAt{69.79}{%
 \HLADefinitionAnchor{pair}\HLADefinitionTerm{pair}: A grouping of two related elements (a first component and a second component), the combination of\linebreak
 which is treated as an entity. An example of a pair would be an instance attribute grouped with its current\linebreak
 value.%
 }

 \HLADefinitionAt{117.78}{%
 \HLADefinitionAnchor{parameter}\HLADefinitionTerm{parameter}: A named characteristic of an interaction.%
 }

 \HLADefinitionAt{141.78}{%
 \HLADefinitionAnchor{passel}\HLADefinitionTerm{passel}: A group of attribute handle/value pairs from an \emph{Update Attribute Values} service invocation that are\linebreak
 delivered together via a \emph{Reflect Attribute Values \textdagger{}} service invocation. All pairs within the passel have the\linebreak
 same user-supplied tag, sent message order type, transportation type, receive message order type, timestamp\linebreak
 (if present), and set of sent region designators (if present). A passel is a message.%
 }

 \HLADefinitionAt{201.78}{%
 \HLADefinitionAnchor{passive-subscription}\HLADefinitionTerm{passive subscription}: A request to the runtime infrastructure (RTI) for the kinds of data (object classes and\linebreak
 attributes as well as interactions) that the joined federate is currently interested in receiving. However, unlike\linebreak
 an active subscription, this information is not used by the RTI to arrange for data to be delivered, nor is it\linebreak
 used to tell publishing joined federates that another joined federate is subscribing to that data (by way of\linebreak
 \emph{Start/Stop Registration}, \emph{Turn On/Off Updates}, or \emph{Turn On/Off Interactions} service invocations). This form of\linebreak
 subscription is provided to support certain types of logger joined federates.%
 }

 \HLADefinitionAt{285.78}{%
 \HLADefinitionAnchor{promoted}\HLADefinitionTerm{promoted}: Pertaining to an object instance, as known by a particular joined federate: having a discovered\linebreak
 class that is a superclass of its registered class.%
 }
 \HLADefinitionNoteAt{90}{321.98}{NOTE---See 5.1.3.}

 \HLADefinitionAt{343.81}{%
 \HLADefinitionAnchor{publish}\HLADefinitionTerm{publish}: To announce to a federation the information a federate may provide to the federation.%
 }

 \HLADefinitionAt{367.81}{%
 \HLADefinitionAnchor{published}\HLADefinitionTerm{published}:%
 }

 \HLAFixedAlphaList{100.02}{391.80}{421.98}{8}{%
 \item Pertaining to an object class from the perspective of a given joined federate: having at least one\linebreak
 available attribute of the object class that was an argument, along with the object class, to a \emph{Publish}\linebreak
 \emph{Object Class Attributes} service invocation that was not subsequently unpublished via the \emph{Unpublish}\linebreak
 \emph{Object Class Attributes} service.\par\vspace{9.4pt}{\fontsize{9pt}{12pt}\selectfont NOTE---See 5.1.2.}
 \item Pertaining to an interaction class from the perspective of a given joined federate: being an argument\linebreak
 to a \emph{Publish Interaction Class} service invocation that was not subsequently followed by an\linebreak
 \emph{Unpublish Interaction Class} service invocation for that interaction class.\par\vspace{9.4pt}{\fontsize{9pt}{12pt}\selectfont NOTE---See 5.1.3.}
 }

 \HLADefinitionAt{537.79}{%
 \HLADefinitionAnchor{published-attributes-of-an-object-class}\HLADefinitionTerm{published attributes of an object class}: The class attributes that have been arguments to \emph{Publish Object}\linebreak
 \emph{Class Attributes} service invocations by a given joined federate for that object class that have not\linebreak
 subsequently been unpublished (either individually or by unpublishing the whole object class), and possibly\linebreak
 the \textbf{HLAprivilegeToDeleteObject} attribute for that object class.%
 }
 \HLADefinitionNoteAt{90}{597.98}{NOTE---See 5.1.2.}

 \HLADefinitionAt{619.81}{%
 \HLADefinitionAnchor{range}\HLADefinitionTerm{range}: A subset of a dimension, defined by an ordered pair of values, the first being the range lower bound\linebreak
 and the second being the range upper bound. This pair of values defines a semi-open interval [range lower\linebreak
 bound, range upper bound) (i.e., the range lower bound is the smallest member of the interval, and the range\linebreak
 upper bound is just greater than any member of the interval).%
 }
 \HLADefinitionNoteAt{90}{680.00}{NOTE---See 9.1.1.}
\end{hlafixedpage}
\clearpage

\HLASourcePage{32}{31}
\thispagestyle{hla-body}
\begin{hlafixedpage}
 \HLADefinitionAt{69.79}{%
 \HLADefinitionAnchor{range-lower-bound}\HLADefinitionTerm{range lower bound}: The first component of the ordered pair of values that is part of a range.%
 }
 \HLADefinitionNoteAt{90}{93.98}{NOTE---See 9.1.}

 \HLADefinitionAt{115.81}{%
 \HLADefinitionAnchor{range-upper-bound}\HLADefinitionTerm{range upper bound}: The second component of the ordered pair of values that is part of a range.%
 }
 \HLADefinitionNoteAt{90}{139.94}{NOTE---See 9.1.}

 \HLADefinitionAt{161.77}{%
 \HLADefinitionAnchor{received-class}\HLADefinitionTerm{received class}: The class that was an interaction's candidate received class at the joined federate when that\linebreak
 interaction was received at that joined federate via an invocation of the \emph{Receive Interaction \textdagger{}} or \emph{Receive}\linebreak
 \emph{Directed Interaction \textdagger{}} service.%
 }
 \HLADefinitionNoteAt{90}{209.96}{NOTE---See 5.1.3.}

 \HLADefinitionAt{231.79}{%
 \HLADefinitionAnchor{received-parameters}\HLADefinitionTerm{received parameters}: The set of parameters received when the \emph{Receive Interaction \textdagger{}} or \emph{Receive Directed}\linebreak
 \emph{Interaction \textdagger{}} service is invoked. These parameters consist of the subset of the sent parameters of an\linebreak
 interaction that are available parameters of the interaction's received class.%
 }
 \HLADefinitionNoteAt{90}{279.98}{NOTE---See 5.1.3.}

 \HLADefinitionAt{301.81}{%
 \HLADefinitionAnchor{receive-order}\HLADefinitionTerm{receive order (RO)}: A characteristic of no ordering guarantee for messages. Messages that are received as\linebreak
 RO messages will be received in an arbitrary order by the respective joined federate. A timestamp value will\linebreak
 be provided with the message if one was specified when the message was sent, but that timestamp has no\linebreak
 bearing on message receipt order.%
 }

 \HLADefinitionAt{361.80}{%
 \HLADefinitionAnchor{reflect}\HLADefinitionTerm{reflect}: To receive new values for one or more instance attributes via invocation of the \emph{Reflect Attribute}\linebreak
 \emph{Values \textdagger{}} service.%
 }
 \HLADefinitionNoteAt{90}{398.00}{NOTE---See 6.11.}

 \HLADefinitionAt{419.77}{%
 \HLADefinitionAnchor{reflected-instance-attribute}\HLADefinitionTerm{reflected instance attribute}: An instance attribute that is represented but not explicitly modeled in a joined\linebreak
 federate. The reflecting joined federate accepts new values of the reflected instance attribute as they are\linebreak
 produced by some other federation member and provided to it by the runtime infrastructure (RTI), via the\linebreak
 \emph{Reflect Attribute Values \textdagger{}} service.%
 }

 \HLADefinitionAt{479.83}{%
 \HLADefinitionAnchor{region}\HLADefinitionTerm{region}: A generic term that refers to either a region specification or a region realization. If not using data\linebreak
 distribution management (DDM), region arguments may be ignored.%
 }
 \HLADefinitionNoteAt{90}{515.96}{NOTE---See 9.1.}

 \HLADefinitionAt{537.79}{%
 \HLADefinitionAnchor{region-realization}\HLADefinitionTerm{region realization}: A region specification (set of ranges) that is associated with an instance attribute for\linebreak
 update, with a sent interaction, or with a class attribute or interaction class for subscription. Region\linebreak
 realizations are created from region specifications via the \emph{Commit Region Modifications} (only when\linebreak
 modifying a region specification from which region realizations are already derived), \emph{Register Object}\linebreak
 \emph{Instance With Regions}, \emph{Associate Regions for Updates}, \emph{Subscribe Object Class Attributes With Regions},\linebreak
 \emph{Subscribe Interaction Class With Regions}, \emph{Send Interaction With Regions}, or \emph{Request Attribute Value}\linebreak
 \emph{Update With Regions} services.%
 }
 \HLADefinitionNoteAt{90}{633.98}{NOTE---See 9.1.1.}

 \HLADefinitionAt{655.81}{%
 \HLADefinitionAnchor{region-specification}\HLADefinitionTerm{region specification}: A set of ranges. Region specifications are created using the \emph{Create Region} service, and\linebreak
 a runtime infrastructure (RTI) is notified of changes to a region specification using the \emph{Commit Region}\linebreak
 \emph{Modifications} service.%
 }
 \HLADefinitionNoteAt{90}{703.81}{NOTE---See 9.1.1.}
\end{hlafixedpage}
\clearpage

\HLASourcePage{35}{34}
\thispagestyle{hla-body}
\begin{hlafixedpage}
 \HLADefinitionAt{69.79}{%
 \HLADefinitionAnchor{subscribed-attributes-of-an-object-class}\HLADefinitionTerm{subscribed attributes of an object class}: The class attributes that have been arguments to \emph{Subscribe Object}\linebreak
 \emph{Class Attributes} service invocations by a given joined federate for a given object class that have not\linebreak
 subsequently been unsubscribed, either individually or by unsubscribing the whole object class.%
 }
 \HLADefinitionNoteAt{90}{114.98}{NOTE---See 5.1.2 and 5.8.}

 \HLADefinitionAt{136.81}{%
 \HLADefinitionAnchor{subscribed-attributes-of-an-object-class-with-regions}\HLADefinitionTerm{subscribed attributes of an object class with regions}: The class attributes that have been arguments to\linebreak
 \emph{Subscribe Object Class Attributes With Regions} service invocations by a given joined federate for a given\linebreak
 object class and a given region, assuming the joined federate did not subsequently invoke the \emph{Unsubscribe}\linebreak
 \emph{Object Class Attributes With Regions} service for that object class and region.%
 }
 \HLADefinitionNoteAt{90}{192.98}{NOTE---See 9.8.}

 \HLADefinitionAt{214.81}{%
 \HLADefinitionAnchor{subscribed-interaction-class}\HLADefinitionTerm{subscribed interaction class}: An interaction class that, from the perspective of a given joined federate, was\linebreak
 an argument to a \emph{Subscribe Interaction Class} or \emph{Subscribe Interaction Class With Regions} service\linebreak
 invocation that was not subsequently followed by an \emph{Unsubscribe Interaction Class} or \emph{Unsubscribe}\linebreak
 \emph{Interaction Class With Regions} service invocation for that interaction class.%
 }
 \HLADefinitionNoteAt{90}{275.00}{NOTE---See 5.1.3 and 5.10.}

 \HLADefinitionAt{296.77}{%
 \HLADefinitionAnchor{subscribed-interaction-class-with-regions}\HLADefinitionTerm{subscribed interaction class with regions}: An interaction class and a region that, from the perspective of a\linebreak
 given joined federate, were arguments to a \emph{Subscribe Interaction Class With Regions} service invocation that\linebreak
 was not subsequently followed by an \emph{Unsubscribe Interaction Class With Regions} service invocation for that\linebreak
 interaction class and that region.%
 }
 \HLADefinitionNoteAt{90}{356.96}{NOTE---See 9.10.}

 \HLADefinitionAt{378.79}{%
 \HLADefinitionAnchor{subscription-region-set}\HLADefinitionTerm{subscription region set}: A set of regions used for subscription of a class attribute or used for subscription of\linebreak
 an interaction class. \emph{See also}: \textbf{used for subscription of a class attribute}; \textbf{used for subscription of an}\linebreak
 \textbf{interaction class}.%
 }

 \HLADefinitionAt{426.78}{%
 \HLADefinitionAnchor{superclass}\HLADefinitionTerm{superclass}: A class that generalizes a set of properties that may be inherited by more refined (i.e., detailed)\linebreak
 versions of the class. In High Level Architecture (HLA) applications, a class may have at most one\linebreak
 immediate superclass (i.e., can inherit only from a single class at the next higher level of the class hierarchy).%
 }

 \HLADefinitionAt{474.78}{%
 \HLADefinitionAnchor{synchronization-point}\HLADefinitionTerm{synchronization point}: A logical point in the sequence of a federation execution that all joined federates\linebreak
 forming a synchronization set for that point attempt to reach and by which, if they are successful, they\linebreak
 synchronize their respective processing.%
 }

 \HLADefinitionAt{522.78}{%
 \HLADefinitionAnchor{target-object-instance}\HLADefinitionTerm{target object instance}: An object instance for which a directed interaction is intended.%
 }

 \HLADefinitionAt{546.78}{%
 \HLADefinitionAnchor{time-advancing-state}\HLADefinitionTerm{time advancing state}: The interval between a joined federate's request to advance its time position and the\linebreak
 corresponding grant by the runtime infrastructure (RTI). A joined federate may advance its time position\linebreak
 only by requesting a time advancement from the RTI via one of the following services:%
 }

 \HLAFixedAlphaList{100.02}{594.78}{421.98}{0}{%
 \item \emph{Time Advance Request}
 \item \emph{Time Advance Request Available}
 \item \emph{Next Message Request}
 \item \emph{Next Message Request Available}
 \item \emph{Flush Queue Request}
 }

 \HLAFixedBlock{90}{664.80}{432}{\rmfamily}{9.96}{12}{%
 The joined federate's time position will not actually be advanced until the RTI responds with a \emph{Time}\linebreak
 \emph{Advance Grant} \textdagger{} or \emph{Flush Queue Grant} \textdagger{} service invocation at that joined federate.%
 }
\end{hlafixedpage}
\clearpage

\HLASourcePage{36}{35}
\thispagestyle{hla-body}
\begin{hlafixedpage}
 \HLADefinitionAt{69.79}{%
 \HLADefinitionAnchor{time-axis}\HLADefinitionTerm{time axis}: A totally ordered sequence of discrete values in which each value typically represents an HLA\linebreak
 instant of time in the physical system being modeled. For any two points, T1 and T2, on the time axis, if T1\linebreak
 < T2, T1 represents an instant of time that occurs before the instant represented by T2. The sequence begins\linebreak
 with an initial value, for which no point is less, and ends with a final value, for which no point is greater.%
 }

 \HLADefinitionAt{123.78}{%
 \HLADefinitionAnchor{time-constrained-federate}\HLADefinitionTerm{time-constrained federate}: A joined federate that may receive timestamp order (TSO) messages and whose\linebreak
 time advances are constrained by other joined federates within a federation execution.%
 }
 \HLADefinitionNoteAt{90}{155.96}{NOTE---See 8.1.}

 \HLADefinitionAt{175.81}{%
 \HLADefinitionAnchor{time-management}\HLADefinitionTerm{time management}: A collection of High Level Architecture (HLA) services that support controlled\linebreak
 message ordering and delivery to the cooperating joined federates within a federation execution in a way\linebreak
 that is consistent with federation requirements.%
 }

 \HLADefinitionAt{218.77}{%
 \HLADefinitionAnchor{time-position}\HLADefinitionTerm{time position}: A joined federate's association with a point on the time axis.%
 }

 \HLADefinitionAt{240.78}{%
 \HLADefinitionAnchor{time-regulating-federate}\HLADefinitionTerm{time-regulating federate}: A joined federate that may send timestamp order (TSO) messages and that\linebreak
 constrains the time advances of other joined federates within a federation execution.%
 }
 \HLADefinitionNoteAt{90}{275.00}{NOTE---See 8.1.}

 \HLADefinitionAt{294.79}{%
 \HLADefinitionAnchor{timestamp-of-message-or-save}\HLADefinitionTerm{timestamp (of message or save)}: The association of a logical time with an activity of a federate (e.g.,\linebreak
 updating instance attribute values, sending interactions, and federation save).%
 }

 \HLADefinitionAt{328.81}{%
 \HLADefinitionAnchor{timestamp-order}\HLADefinitionTerm{timestamp order (TSO)}: An ordering of messages provided by a runtime infrastructure (RTI) for joined\linebreak
 federates making use of time management services and messages containing timestamps. Messages having\linebreak
 different timestamps are said to be delivered in TSO if for any two messages, M1 and M2 (timestamped with\linebreak
 T1 and T2, respectively), that are delivered to a single joined federate where T1 < T2, then M1 is delivered\linebreak
 before M2. Messages having the same timestamp will be delivered in an arbitrary order (i.e., no tie-breaking\linebreak
 mechanism is provided by an RTI).%
 }

 \HLADefinitionAt{410.76}{%
 \HLADefinitionAnchor{transportation-type}\HLADefinitionTerm{transportation type}: A runtime infrastructure (RTI) provided means of transmitting messages between\linebreak
 joined federates. Different categories of service are defined with different characteristics such as reliability\linebreak
 of delivery and message latency.%
 }

 \HLADefinitionAt{453.78}{%
 \HLADefinitionAnchor{unspecified-dimensions}\HLADefinitionTerm{unspecified dimensions}: The available dimensions of a class attribute, instance attribute, interaction class,\linebreak
 or sent interaction less the specified dimensions of the region specification from which the region realization\linebreak
 is derived.%
 }
 \HLADefinitionNoteAt{90}{497.00}{NOTE---See 9.1.3.}

 \HLADefinitionAt{516.79}{%
 \HLADefinitionAnchor{update}\HLADefinitionTerm{update}: To invoke the \emph{Update Attribute Values} service for one or more instance attributes.%
 }
 \HLADefinitionNoteAt{90}{539.00}{NOTE---See 6.10.}

 \HLADefinitionAt{558.79}{%
 \HLADefinitionAnchor{update-rate}\HLADefinitionTerm{update rate}: The rate at which instance attribute values are provided, either by an owning joined federate to\linebreak
 the runtime infrastructure (RTI) or by the RTI to a subscribing joined federate.%
 }

 \HLADefinitionAt{592.80}{%
 \HLADefinitionAnchor{update-region-set}\HLADefinitionTerm{update region set}: A set of regions used for sending interactions or used for updating of instance attributes.\linebreak
 \emph{See also}: \textbf{used for sending}; \textbf{used for update}.%
 }

 \HLADefinitionAt{624.78}{%
 \HLADefinitionAnchor{used-for-sending}\HLADefinitionTerm{used for sending}:%
 }

 \HLAFixedAlphaList{100.02}{646.80}{421.98}{5}{%
 \item Pertaining to a region and the specified interaction class designator: being an argument in the \emph{Send}\linebreak
 \emph{Interaction With Regions} service.
 \item Pertaining to the default region: when the specified interaction class designator is an argument in the\linebreak
 \emph{Send Interaction} service.
 }
 \HLADefinitionNoteAt{90}{707.00}{NOTE---See 9.1.}
\end{hlafixedpage}
\clearpage

\HLASourcePage{37}{36}
\thispagestyle{hla-body}
\begin{hlafixedpage}
 \HLADefinitionAt{69.79}{%
 \HLADefinitionAnchor{used-for-subscription-of-a-class-attribute}\HLADefinitionTerm{used for subscription of a class attribute}:%
 }
 \HLAFixedAlphaListFrom{100.02}{93.79}{421.98}{0}{1}{%
 \item Pertaining to a region, an object class, and a class attribute: when the class attribute is a subscribed\linebreak
 attribute of the object class with that region. \emph{See also}: \textbf{subscribed attributes of an object class with}\linebreak
 \textbf{regions}.%
 }
 \HLADefinitionNoteAt{121.98}{139.94}{NOTE---See 9.1.}
 \HLAFixedAlphaListFrom{100.02}{159.79}{421.98}{0}{2}{%
 \item Pertaining to the default region: when the specified class attribute is a subscribed attribute of the\linebreak
 specified class. \emph{See also}: \textbf{subscribed attributes of an object class with regions}.%
 }
 \HLADefinitionNoteAt{121.02}{194.00}{NOTE---See 9.1.}

 \HLADefinitionAt{213.79}{%
 \HLADefinitionAnchor{used-for-subscription-of-an-interaction-class}\HLADefinitionTerm{used for subscription of an interaction class}:%
 }
 \HLAFixedAlphaListFrom{100.02}{237.79}{421.98}{0}{1}{%
 \item Pertaining to a region and an interaction class: when the interaction class is a subscribed interaction\linebreak
 class with regions. \emph{See also}: \textbf{subscribed interaction class}.%
 }
 \HLADefinitionNoteAt{121.02}{272.00}{NOTE---See 9.1.}
 \HLAFixedAlphaListFrom{100.02}{291.79}{421.98}{0}{2}{%
 \item Pertaining to the default region: when the specified interaction class is a subscribed interaction class.\linebreak
 \emph{See also}: \textbf{subscribed interaction class}.%
 }
 \HLADefinitionNoteAt{121.02}{326.00}{NOTE---See 9.1.}

 \HLADefinitionAt{345.79}{%
 \HLADefinitionAnchor{used-for-update}\HLADefinitionTerm{used for update}:%
 }
 \HLAFixedAlphaListFrom{100.02}{369.79}{421.98}{0}{1}{%
 \item Pertaining to a region that, along with the specified object instance and attribute designators, has\linebreak
 been used as an argument in either the \emph{Register Object Instance With Regions} service or the\linebreak
 \emph{Associate Regions For Updates} service: when the region has not subsequently been used along with\linebreak
 the specified object instance designator as an argument in the \emph{Unassociate Regions For Updates}\linebreak
 service, nor has the joined federate subsequently lost ownership of the specified instance\linebreak
 attribute(s).%
 }
 \HLADefinitionNoteAt{121.02}{452.00}{NOTE---See 9.1.}
 \HLAFixedAlphaListFrom{100.02}{471.79}{421.98}{0}{2}{%
 \item Pertaining to the default region: when the specified instance attribute(s) is not currently used for\linebreak
 update with any other region.%
 }
 \HLADefinitionNoteAt{121.02}{506.00}{NOTE---See 9.1.}

 \HLADefinitionAt{525.79}{%
 \HLADefinitionAnchor{valid-federate-designator}\HLADefinitionTerm{valid federate designator}: A federate designator which, during the federation execution, was returned by\linebreak
 the \emph{Join Federation Execution} service to some joined federate. The federate does not have to remain a joined\linebreak
 federate for its federate designator to remain a valid federate designator.%
 }

 \HLADefinitionAt{573.78}{%
 \HLADefinitionAnchor{wall-clock-time}\HLADefinitionTerm{wall-clock time}: Time as determined by a chronometer such as a wristwatch or wall clock.%
 }

 \HLADefinitionAt{597.78}{%
 \HLADefinitionAnchor{zero-time-interval}\HLADefinitionTerm{zero time interval}: The distance between two logical time values that are equal. This time interval, when\linebreak
 added to a logical time T1, results in a logical time T2 == T1.%
 }
\end{hlafixedpage}
\clearpage

