 \HLAFixedBlock{90.000}{470.686}{159.246}{\sffamily\bfseries\raggedright}{9.96}{12.00}{%
 \textbf{4.1.4 FOM Document Data (FDD)}%
 }
 \HLAFixedBlock{90.000}{494.825}{432.000}{\rmfamily}{9.96}{12.00}{%
 The FDD is data and information extracted and combined from FOM modules in order to support\linebreak%
 }
 \HLAFixedBlock{90.000}{506.825}{432.000}{\rmfamily}{9.96}{12.00}{%
 functionality described in this specification. The FOM module format and rules for combination are defined\linebreak%
 }
 \HLAFixedBlock{90.000}{518.825}{432.000}{\rmfamily}{9.96}{12.00}{%
 in IEEE Std 1516.2-2025. The FDD that the RTI retains and combines from the FOM modules shall be, at a\linebreak%
 }
 \HLAFixedBlock{90.000}{530.825}{106.230}{\rmfamily\raggedright}{9.96}{12.00}{%
 minimum, the following:%
 }
 \HLAFixedBlock{100.020}{554.824}{15.960}{\rmfamily\raggedright}{9.96}{12.00}{%
 ---%
 }
 \HLAFixedBlock{121.980}{554.824}{159.833}{\rmfamily\raggedright}{9.96}{12.00}{%
 Object class structure table (complete)%
 }
 \HLAFixedBlock{100.020}{566.824}{15.960}{\rmfamily\raggedright}{9.96}{12.00}{%
 ---%
 }
 \HLAFixedBlock{121.981}{566.824}{176.504}{\rmfamily\raggedright}{9.96}{12.00}{%
 Interaction class structure table (complete)%
 }
 \HLAFixedBlock{100.020}{578.824}{15.960}{\rmfamily\raggedright}{9.96}{12.00}{%
 ---%
 }
 \HLAFixedBlock{121.980}{578.824}{148.917}{\rmfamily\raggedright}{9.96}{12.00}{%
 Directed interation table (complete)%
 }
 \HLAFixedBlock{100.020}{590.824}{15.960}{\rmfamily\raggedright}{9.96}{12.00}{%
 ---%
 }
 \HLAFixedBlock{121.980}{590.824}{275.825}{\rmfamily\raggedright}{9.96}{12.00}{%
 Attribute table (object, attribute, transportation, and order columns)%
 }
 \HLAFixedBlock{100.020}{602.823}{15.960}{\rmfamily\raggedright}{9.96}{12.00}{%
 ---%
 }
 \HLAFixedBlock{121.980}{602.823}{304.927}{\rmfamily\raggedright}{9.96}{12.00}{%
 Parameter table (interaction, parameter, transportation, and order columns)%
 }
 \HLAFixedBlock{100.020}{614.823}{15.960}{\rmfamily\raggedright}{9.96}{12.00}{%
 ---%
 }
 \HLAFixedBlock{121.980}{614.823}{117.606}{\rmfamily\raggedright}{9.96}{12.00}{%
 Dimension table (complete)%
 }
 \HLAFixedBlock{100.020}{626.823}{15.960}{\rmfamily\raggedright}{9.96}{12.00}{%
 ---%
 }
 \HLAFixedBlock{121.980}{626.823}{231.585}{\rmfamily\raggedright}{9.96}{12.00}{%
 Transportation type table (name and reliability columns)%
 }
 \HLAFixedBlock{100.020}{638.823}{15.960}{\rmfamily\raggedright}{9.96}{12.00}{%
 ---%
 }
 \HLAFixedBlock{121.980}{638.823}{248.047}{\rmfamily\raggedright}{9.96}{12.00}{%
 Update rate table (name and maximum update rate columns)%
 }
 \HLAFixedBlock{100.020}{650.823}{15.960}{\rmfamily\raggedright}{9.96}{12.00}{%
 ---%
 }
 \HLAFixedBlock{121.980}{650.823}{109.856}{\rmfamily\raggedright}{9.96}{12.00}{%
 Switches table (complete)%
 }
 \HLAFixedBlock{90.000}{674.822}{216.940}{\rmfamily\raggedright}{9.96}{12.00}{%
 All the names within an FDD shall be case sensitive.%
 }
