 \HLAServiceHeadingAt{69.383}{%
 4.2 \emph{Connect} service%
 }
 \HLAFixedBlock{90.000}{94.806}{433.233}{\rmfamily}{9.96}{12.00}{%
 \SemanticRequirementReqConnectServiceEstablishesConnectionStatement
 }
 \HLAFixedBlock{89.999}{142.805}{411.858}{\rmfamily\raggedright}{9.96}{12.00}{%
 The callback model argument indicates the desired callback model, either IMMEDIATE or EVOKED.
 }
 \HLAFixedBlock{89.999}{166.805}{433.214}{\rmfamily}{9.96}{12.00}{%
 The configuration name designates a named configuration that shall be used. If no configuration name is\linebreak%
 specified, or if no configuration with the specified name is found, the implementation’s default\linebreak%
 configuration shall be used.
 }
 \HLAFixedBlock{89.999}{214.804}{433.245}{\rmfamily}{9.96}{12.00}{%
 The RTI Address argument provides an implementation-dependent value that the RTI can use to locate other\linebreak%
 parts of the RTI. If no RTI Address value is specified, the RTI shall use an address from the designated\linebreak%
 configuration or the implementations default address.
 }
 \HLAFixedBlock{89.999}{262.803}{433.202}{\rmfamily}{9.96}{12.00}{%
 The optional additional settings argument can be used to pass implementation-specific settings to the RTI.\linebreak%
 The RTI is not required to use these settings. Failure to parse these settings shall not stop the RTI from\linebreak%
 completing the connection.
 }
 \HLAFixedBlock{89.999}{310.802}{433.206}{\rmfamily}{9.96}{12.00}{%
 If the RTI is configured to require authorization, the RTI shall require that valid credentials (type and data)\linebreak%
 are provided.
 }
 \HLAFixedBlock{89.999}{346.802}{433.227}{\rmfamily}{9.96}{12.00}{%
 The return value indicates if the RTI was able to parse and use the optional additional settings. The return\linebreak%
 value consists of two parts, a return code and a message string. The possible values for the return code are:
 }
 \HLAFixedBlock{100.019}{373.801}{11.160}{\rmfamily\raggedright}{9.96}{12.00}{%
 ---
 }
 \HLAFixedBlock{121.979}{373.801}{400.021}{\rmfamily\raggedright}{9.96}{12.00}{%
 IgnoredSettings
 }
 \HLAFixedBlock{100.019}{388.801}{11.160}{\rmfamily\raggedright}{9.96}{12.00}{%
 ---
 }
 \HLAFixedBlock{121.979}{388.801}{400.021}{\rmfamily\raggedright}{9.96}{12.00}{%
 FailedToParseSettings
 }
 \HLAFixedBlock{100.019}{403.801}{11.160}{\rmfamily\raggedright}{9.96}{12.00}{%
 ---
 }
 \HLAFixedBlock{121.979}{403.801}{400.021}{\rmfamily\raggedright}{9.96}{12.00}{%
 AppliedSettings
 }
 \HLAFixedBlock{89.999}{427.801}{433.161}{\rmfamily}{9.96}{12.00}{%
 For each of these return codes, the message string may contain a human-readable message with more\linebreak%
 information.
 }
