 }
 \HLAFixedBlock{121.979}{622.800}{400.021}{\rmfamily\raggedright}{9.96}{12.00}{%
 Federation save-success indicator.%
 }
 \HLAFixedBlock{100.019}{634.800}{421.981}{\rmfamily\raggedright}{9.96}{12.00}{%
 b)%
 }
 \HLAFixedBlock{121.979}{634.800}{400.021}{\rmfamily\raggedright}{9.96}{12.00}{%
 Optional failure reason.%
 }
