 \HLAServiceHeadingAt{69.383}{%
 4.26 \emph{Federation Save Status Response \textdagger{}} service%
 }
 \HLAFixedBlock{90.000}{94.806}{432.000}{\rmfamily\raggedright}{9.96}{12.00}{%
 The \emph{Federation Save Status Response \textdagger{}} service shall be used to provide the status of a federation save. This%
 }
 \HLAFixedBlock{90.000}{106.806}{432.000}{\rmfamily\raggedright}{9.96}{12.00}{%
 service shall be invoked by the RTI at a joined federate in response to a \emph{Query Federation Save Status}%
 }
 \HLAFixedBlock{90.000}{118.805}{432.000}{\rmfamily\raggedright}{9.96}{12.00}{%
 service invocation by the same joined federate. This service shall supply a list of the joined federates%
 }
 \HLAFixedBlock{90.000}{130.805}{432.000}{\rmfamily\raggedright}{9.96}{12.00}{%
 participating in the federation save and the save status for each one. A joined federate save status shall be%
 }
 \HLAFixedBlock{90.000}{142.805}{432.000}{\rmfamily\raggedright}{9.96}{12.00}{%
 one of the following values:%
 }
 \HLAFixedBlock{100.020}{157.805}{421.980}{\rmfamily\raggedright}{9.96}{12.00}{%
 ---%
 }
 \HLAFixedBlock{121.980}{157.805}{400.020}{\rmfamily\raggedright}{9.96}{12.00}{%
 No federate save in progress%
 }
 \HLAFixedBlock{100.020}{172.805}{421.980}{\rmfamily\raggedright}{9.96}{12.00}{%
 ---%
 }
 \HLAFixedBlock{121.980}{172.805}{400.020}{\rmfamily\raggedright}{9.96}{12.00}{%
 Federate instructed to save%
 }
 \HLAFixedBlock{100.020}{187.804}{421.980}{\rmfamily\raggedright}{9.96}{12.00}{%
 ---%
 }
 \HLAFixedBlock{121.980}{187.804}{400.020}{\rmfamily\raggedright}{9.96}{12.00}{%
 Federate saving %
 }
 \HLAFixedBlock{100.020}{202.804}{421.980}{\rmfamily\raggedright}{9.96}{12.00}{%
 ---%
 }
 \HLAFixedBlock{121.980}{202.804}{400.020}{\rmfamily\raggedright}{9.96}{12.00}{%
 Federate waiting for federation to save%
 }
 \HLAServiceComponentHeadingAt{226.664}{%
 4.26.1 Supplied arguments%
 }
 \HLAFixedBlock{100.020}{250.803}{421.980}{\rmfamily\raggedright}{9.96}{12.00}{%
 a)%
 }
 \HLAFixedBlock{121.979}{250.803}{400.021}{\rmfamily\raggedright}{9.96}{12.00}{%
 List of joined federates and save status for each.%
 }
 \HLAServiceComponentHeadingAt{273.644}{%
 4.26.2 Returned arguments%
 }
