 }
 \HLAFixedBlock{90.000}{641.826}{432.000}{\rmfamily\raggedright}{9.96}{12.00}{%
 The \emph{Federation Restored \textdagger{}} service shall inform the joined federate that the federation restore process is%
 }
 \HLAFixedBlock{90.001}{653.825}{431.999}{\rmfamily\raggedright}{9.96}{12.00}{%
 complete, and it shall indicate whether it completed successfully. A restore-success indicator argument%
 }
 \HLAFixedBlock{90.001}{665.825}{431.999}{\rmfamily\raggedright}{9.96}{12.00}{%
 indicating success shall mean that all joined federates at which the \emph{Federation Restore Begun \textdagger{}} service was%
 }
 \HLAFixedBlock{90.001}{677.825}{431.999}{\rmfamily\raggedright}{9.96}{12.00}{%
 invoked have invoked the \emph{Federate Restore Complete} service with a restore-success indicator that indicated%
 }
 \HLAFixedBlock{90.001}{689.825}{431.999}{\rmfamily\raggedright}{9.96}{12.00}{%
 success.%
 }
