 }
 \HLAFixedBlock{121.977}{513.779}{400.023}{\rmfamily\raggedright}{9.96}{12.00}{%
 \emph{Interactions}, \emph{Unsubscribe Object Class Directed Interactions}, \emph{Publish Object Class Directed}%
 }
 \HLAFixedBlock{121.978}{525.779}{400.022}{\rmfamily\raggedright}{9.96}{12.00}{%
 \emph{Interactions}, and \emph{Unpublish Object Class Directed Interactions} service invocations for a particular%
 }
 \HLAFixedBlock{121.978}{537.778}{400.022}{\rmfamily\raggedright}{9.96}{12.00}{%
 object class if and only if the directed interaction class is an available directed interaction class of%
 }
 \HLAFixedBlock{121.977}{549.778}{400.023}{\rmfamily\raggedright}{9.96}{12.00}{%
