 }
 \HLAFixedBlock{121.978}{585.778}{400.022}{\rmfamily\raggedright}{9.96}{12.00}{%
 \emph{Directed Interactions} service invocations by that joined federate for that object class and that have%
 }
 \HLAFixedBlock{121.978}{597.777}{400.022}{\rmfamily\raggedright}{9.96}{12.00}{%
 not subsequently been unsubscribed, either individually or by unsubscribing the whole object class.%
 }
 \HLAFixedBlock{121.978}{609.777}{400.022}{\rmfamily\raggedright}{9.96}{12.00}{%
 \emph{Subscribe Object Class Directed Interactions} and \emph{Unsubscribe Object Class Directed Interactions}%
 }
 \HLAFixedBlock{121.980}{621.785}{400.020}{\rmfamily\raggedright}{9.96}{12.00}{%
 service invocations for one object class shall have no effect on the subscribed directed interaction%
