 shall be all the directed interaction classes that have been arguments to \emph{Publish Object Class}%
 }
 \HLAFixedBlock{121.981}{669.785}{400.019}{\rmfamily\raggedright}{9.96}{12.00}{%
 \emph{Directed Interactions} service invocations by that joined federate for that object class and that have%
 }
 \HLAFixedBlock{121.981}{681.784}{400.019}{\rmfamily\raggedright}{9.96}{12.00}{%
 not subsequently been unpublished, either individually or by unpublishing the whole object class.%
 }
 \HLAFixedBlock{100.021}{693.784}{421.979}{\rmfamily\raggedright}{9.96}{12.00}{%
 d)%
 }
 \HLAFixedBlock{121.981}{693.784}{400.019}{\rmfamily\raggedright}{9.96}{12.00}{%
 Joined federates may invoke the \emph{Send Directed Interaction} service only with a published class%
 }
 \HLAFixedBlock{121.981}{705.784}{400.019}{\rmfamily\raggedright}{9.96}{12.00}{%
 directed interaction as an argument.%
