 \HLAServiceComponentHeadingAt{571.845}{%
 5.1.6 Interaction with DDM services%
 }
 \HLAFixedBlock{89.999}{595.984}{432.001}{\rmfamily\raggedright}{9.96}{12.00}{%
 A joined federate may use DM services, and it may also use DDM services. Joined federates that use DM%
 }
 \HLAFixedBlock{89.999}{607.024}{432.001}{\rmfamily\raggedright}{9.96}{12.00}{%
 services exclusively may be joined to the same federation execution as joined federates that use DM services%
 }
 \HLAFixedBlock{89.998}{618.004}{432.002}{\rmfamily\raggedright}{9.96}{12.00}{%
 exclusively, joined federates that use DDM services exclusively, and joined federates that use both DM%
 }
 \HLAFixedBlock{89.999}{629.044}{432.001}{\rmfamily\raggedright}{9.96}{12.00}{%
 services and DDM services. Clause 5 describes how DM services work when they are used in the absence of%
 }
 \HLAFixedBlock{89.999}{640.023}{432.001}{\rmfamily\raggedright}{9.96}{12.00}{%
 the use of DDM services by a joined federate, from the perspective of that joined federate, regardless of%
 }
 \HLAFixedBlock{89.999}{651.003}{432.001}{\rmfamily\raggedright}{9.96}{12.00}{%
 whether other joined federates in the federation are using DM services exclusively, DDM services%
 }
 \HLAFixedBlock{89.999}{662.043}{432.001}{\rmfamily\raggedright}{9.96}{12.00}{%
 exclusively, or both DM services and DDM services. When both DM services and DDM services are used%
 }
 \HLAFixedBlock{89.999}{673.023}{432.001}{\rmfamily\raggedright}{9.96}{12.00}{%
 by a single joined federate, some of the terms and services defined in this clause are extended. See 9.1.5 for%
 }
 \HLAFixedBlock{89.999}{684.003}{432.001}{\rmfamily\raggedright}{9.96}{12.00}{%
 an expanded interpretation of how selected DM services work when they are used in conjunction with DDM%
 }
 \HLAFixedBlock{89.998}{695.043}{432.002}{\rmfamily\raggedright}{9.96}{12.00}{%
 services by a joined federate, from the perspective of that joined federate.%
 }
\end{hlafixedpage}
