 }
 \HLAFixedBlock{100.020}{586.799}{421.980}{\rmfamily\raggedright}{9.96}{12.00}{%
 c)%
 }
 \HLAFixedBlock{121.969}{586.799}{400.031}{\rmfamily\raggedright}{9.96}{12.00}{%
 The federate is joined to that federation execution.%
 }
 \HLAFixedBlock{100.020}{598.799}{421.980}{\rmfamily\raggedright}{9.96}{12.00}{%
 d)%
 }
 \HLAFixedBlock{121.938}{598.799}{400.062}{\rmfamily\raggedright}{9.96}{12.00}{%
