 }
 \HLAFixedBlock{100.020}{610.799}{421.980}{\rmfamily\raggedright}{9.96}{12.00}{%
 e)%
 }
 \HLAFixedBlock{121.977}{610.799}{400.023}{\rmfamily\raggedright}{9.96}{12.00}{%
 The specified class attributes are available attributes of the specified object class.%
 }
 \HLAFixedBlock{100.020}{622.799}{421.980}{\rmfamily\raggedright}{9.96}{12.00}{%
 f)%
 }
 \HLAFixedBlock{121.949}{622.799}{400.051}{\rmfamily\raggedright}{9.96}{12.00}{%
