 Federate restore not in progress.%
 }
 \HLAServiceComponentHeadingAt{658.659}{%
 5.2.4 Postconditions%
 }
 \HLAFixedBlock{100.020}{682.798}{421.980}{\rmfamily\raggedright}{9.96}{12.00}{%
 a)%
 }
 \HLAFixedBlock{121.970}{682.798}{400.030}{\rmfamily\raggedright}{9.96}{12.00}{%
 The specified class attributes shall now be published attributes of the specified object class for the%
 }
 \HLAFixedBlock{121.980}{694.798}{400.020}{\rmfamily\raggedright}{9.96}{12.00}{%
 joined federate.%
 }
