 6.13 \emph{Receive Interaction \textdagger{}} service%
 }
 \HLAFixedBlock{90.000}{316.806}{432.000}{\rmfamily\raggedright}{9.96}{12.00}{%
 The \emph{Receive Interaction \textdagger{} }service shall provide the joined federate with a sent interaction.%
 }
 \HLAFixedBlock{90.000}{340.805}{432.000}{\rmfamily\raggedright}{9.96}{12.00}{%
 The user-supplied tag argument supplied to the corresponding \emph{Send Interaction} or \emph{Send Interaction With}%
 }
 \HLAFixedBlock{90.000}{352.805}{432.000}{\rmfamily\raggedright}{9.96}{12.00}{%
 \emph{Regions }service invocation shall be provided with all corresponding \emph{Receive Interaction \textdagger{}} service%
 }
 \HLAFixedBlock{90.000}{364.805}{432.000}{\rmfamily\raggedright}{9.96}{12.00}{%
 invocations.%
 }
 \HLAFixedBlock{90.000}{388.804}{432.000}{\rmfamily\raggedright}{9.96}{12.00}{%
 The transportation type argument shall indicate the transportation type of the specified interaction, i.e., the%
 }
 \HLAFixedBlock{90.000}{400.804}{432.000}{\rmfamily\raggedright}{9.96}{12.00}{%
 transportation type of the published interaction at the joined federate that invoked the corresponding \emph{Send}%
 }
 \HLAFixedBlock{90.000}{412.804}{432.000}{\rmfamily\raggedright}{9.96}{12.00}{%
 \emph{Interaction} or \emph{Send Interaction With Regions }service.%
 }
 \HLAFixedBlock{90.000}{436.804}{432.000}{\rmfamily\raggedright}{9.96}{12.00}{%
 A timestamp shall be provided if one was specified in the corresponding \emph{Send Interaction} or \emph{Send}%
 }
 \HLAFixedBlock{89.999}{448.804}{432.001}{\rmfamily\raggedright}{9.96}{12.00}{%
 \emph{Interaction With Regions }service invocation. The receive message order type shall indicate the type (either%
 }
 \HLAFixedBlock{90.000}{460.803}{432.000}{\rmfamily\raggedright}{9.96}{12.00}{%
 RO or TSO) of the received message. The timestamp and receive message order type arguments shall be%
 }
 \HLAFixedBlock{90.000}{472.803}{432.000}{\rmfamily\raggedright}{9.96}{12.00}{%
 supplied together or not at all. The sent message order type shall indicate the type (either RO or TSO) of the%
 }
 \HLAFixedBlock{90.000}{484.803}{432.000}{\rmfamily\raggedright}{9.96}{12.00}{%
 sent message. %
 }
 \HLAFixedBlock{90.000}{508.803}{432.000}{\rmfamily\raggedright}{9.96}{12.00}{%
 A retraction handle shall be provided if and only if the sent message order type is TSO.%
 }
 \HLAFixedBlock{90.000}{532.802}{432.000}{\rmfamily\raggedright}{9.96}{12.00}{%
 If the specified interaction has available dimensions and the Convey Region Designator Sets Switch for this%
 }
 \HLAFixedBlock{90.000}{544.802}{432.000}{\rmfamily\raggedright}{9.96}{12.00}{%
 joined federate is enabled, the Set of Sent Region Designators argument shall contain a copy of the update%
 }
 \HLAFixedBlock{90.000}{556.802}{432.000}{\rmfamily\raggedright}{9.96}{12.00}{%
 region realization (see 9.1.7), if any, that was supplied to the corresponding \emph{Send Interaction With Regions}%
 }
 \HLAFixedBlock{90.000}{568.802}{432.000}{\rmfamily\raggedright}{9.96}{12.00}{%
 service invocation by the sending joined federate.%
 }
 \HLAFixedBlock{90.000}{592.801}{432.000}{\rmfamily\raggedright}{9.96}{12.00}{%
 The producing joined federate argument shall contain the designator for the sending joined federate%
 }
 \HLAFixedBlock{90.000}{616.801}{432.000}{\rmfamily\raggedright}{9.96}{12.00}{%
 A joined federate invoking the \emph{Send Interaction} or \emph{Send Interaction With Regions }service shall not receive%
 }
 \HLAFixedBlock{90.000}{628.801}{432.000}{\rmfamily\raggedright}{9.96}{12.00}{%
 the induced \emph{Receive Interaction \textdagger{} }service invocation, regardless of the subscription situation.%
 }
 \HLAFixedBlock{90.000}{652.800}{432.000}{\rmfamily\raggedright}{9.96}{12.00}{%
 At most, one induced \emph{Receive Interaction \textdagger{} }service invocation shall happen at a joined federate as a result of%
 }
 \HLAFixedBlock{90.001}{664.800}{431.999}{\rmfamily\raggedright}{9.96}{12.00}{%
 the invocation of the \emph{Send Interaction} or \emph{Send Interaction With Regions} service at another joined federate.%
 }
\end{hlafixedpage}
