 \HLAFixedBlock{142.018}{633.777}{379.982}{\rmfamily\raggedright}{9.96}{12.00}{%
 the object instance immediately becomes unknown to the joined federate and ceases to exist as%
 }
 \HLAFixedBlock{142.018}{645.776}{379.982}{\rmfamily\raggedright}{9.96}{12.00}{%
 far as the joined federate is concerned. The object instance may still be discovered by other%
 }
 \HLAFixedBlock{142.018}{657.776}{379.982}{\rmfamily\raggedright}{9.96}{12.00}{%
 joined federates until their time positions are greater or equal to the specified timestamp of the%
 }
 \HLAFixedBlock{142.018}{669.776}{379.982}{\rmfamily\raggedright}{9.96}{12.00}{%
 deletion.%
 }
