 }
 \HLAFixedBlock{90.001}{191.765}{431.999}{\rmfamily\raggedright}{9.96}{12.00}{%
 The user-supplied tag argument supplied to the corresponding \emph{Request Attribute Value Update} service%
 }
 \HLAFixedBlock{90.001}{202.804}{431.999}{\rmfamily\raggedright}{9.96}{12.00}{%
 invocation shall be provided with all corresponding \emph{Provide Attribute Value Update \textdagger{}} service invocations.%
 }
 \HLAFixedBlock{90.001}{223.804}{431.999}{\rmfamily\raggedright}{9.96}{12.00}{%
 A single \emph{Request Attribute Value Update} shall result in at most one \emph{Provide Attribute Value Update \textdagger{}}%
 }
 \HLAFixedBlock{90.001}{234.784}{431.999}{\rmfamily\raggedright}{9.96}{12.00}{%
