 }
 \HLAFixedBlock{90.000}{519.785}{432.000}{\rmfamily\raggedright}{9.96}{12.00}{%
 transportation type for its class in the creating federate. A joined federate may choose to change the%
 }
 \HLAFixedBlock{90.000}{531.785}{432.000}{\rmfamily\raggedright}{9.96}{12.00}{%
 transportation type during execution. Invoking the \emph{Request Attribute Transportation Type Change} service%
 }
 \HLAFixedBlock{90.000}{543.785}{432.000}{\rmfamily\raggedright}{9.96}{12.00}{%
 shall attempt to change the transportation type for all future \emph{Update Attribute Values} service invocations for%
 }
 \HLAFixedBlock{90.000}{555.785}{432.000}{\rmfamily\raggedright}{9.96}{12.00}{%
 the specified attributes of the specified object instance only for the invoking joined federate. The RTI shall%
 }
 \HLAFixedBlock{90.000}{567.785}{432.000}{\rmfamily\raggedright}{9.96}{12.00}{%
 provide the achieved transportation type via the \emph{Confirm Attribute Transportation Type Change \textdagger{} }service%
 }
 \HLAFixedBlock{90.000}{579.784}{432.000}{\rmfamily\raggedright}{9.96}{12.00}{%
 invocation. The change shall take effect with the RTI invocation of the responding \emph{Confirm Attribute}%
 }
 \HLAFixedBlock{90.000}{591.784}{432.000}{\rmfamily\raggedright}{9.96}{12.00}{%
 \emph{Transportation Type Change \textdagger{} }service\emph{. }If the invoking joined federate loses ownership of an instance%
 }
 \HLAFixedBlock{90.000}{603.784}{432.000}{\rmfamily\raggedright}{9.96}{12.00}{%
 attribute after changing its transportation type and later acquires ownership of that instance attribute again,%
 }
 \HLAFixedBlock{90.000}{615.784}{432.000}{\rmfamily\raggedright}{9.96}{12.00}{%
