 \HLAServiceHeadingAt{445.403}{%
 \textbf{8.12 }\textbf{\emph{Flush Queue Request}}\textbf{ service}%
 }
 \HLAFixedBlock{90.000}{470.766}{432.000}{\rmfamily\raggedright}{9.96}{12.00}{%
 The \emph{Flush Queue Request} service shall request that all messages queued in the RTI that the joined federate%
 }
 \HLAFixedBlock{90.001}{482.825}{431.999}{\rmfamily\raggedright}{9.96}{12.00}{%
 will receive as TSO messages be delivered now. The RTI shall deliver all such messages as soon as possible,%
 }
 \HLAFixedBlock{90.001}{494.825}{431.999}{\rmfamily\raggedright}{9.96}{12.00}{%
 despite the fact that it may not be able to guarantee that no future messages containing smaller timestamps%
 }
 \HLAFixedBlock{90.001}{506.825}{431.999}{\rmfamily\raggedright}{9.96}{12.00}{%
 could arrive. The RTI shall advance the joined federate’s logical time to the smallest of the following:%
 }
 \HLAFixedBlock{100.021}{521.825}{421.979}{\rmfamily\raggedright}{9.96}{12.00}{%
 ---%
 }
 \HLAFixedBlock{121.981}{521.825}{400.019}{\rmfamily\raggedright}{9.96}{12.00}{%
 The specified logical time%
 }
 \HLAFixedBlock{100.021}{536.824}{421.979}{\rmfamily\raggedright}{9.96}{12.00}{%
 ---%
 }
 \HLAFixedBlock{121.981}{536.824}{400.019}{\rmfamily\raggedright}{9.96}{12.00}{%
 The joined federate’s GALT value%
 }
 \HLAFixedBlock{100.021}{551.824}{421.979}{\rmfamily\raggedright}{9.96}{12.00}{%
 ---%
 }
 \HLAFixedBlock{121.981}{551.824}{400.019}{\rmfamily\raggedright}{9.96}{12.00}{%
 The smallest timestamp of all TSO messages delivered by the RTI in response to this invocation of%
 }
 \HLAFixedBlock{121.981}{563.824}{400.019}{\rmfamily\raggedright}{9.96}{12.00}{%
 the \emph{Flush Queue Request} service%
 }
 \HLAFixedBlock{90.000}{587.823}{432.000}{\rmfamily\raggedright}{9.96}{12.00}{%
 The RTI shall also provide an optimistic logical time that the RTI would grant the federate to if the logical%
 }
 \HLAFixedBlock{90.000}{599.823}{432.000}{\rmfamily\raggedright}{9.96}{12.00}{%
 time were not constrained by the federate’s GALT. If GALT is not the determining value in advancing the%
 }
 \HLAFixedBlock{90.000}{611.823}{432.000}{\rmfamily\raggedright}{9.96}{12.00}{%
 joined federate’s logical time, the logical time and optimistic logical time shall be the same.%
 }
 \HLAFixedBlock{90.000}{635.823}{432.000}{\rmfamily\raggedright}{9.96}{12.00}{%
 Invocation of this service shall cause the following set of messages to be delivered to the joined federate: %
 }
 \HLAFixedBlock{100.020}{650.823}{421.980}{\rmfamily\raggedright}{9.96}{12.00}{%
 ---%
 }
 \HLAFixedBlock{121.979}{650.823}{400.021}{\rmfamily\raggedright}{9.96}{12.00}{%
 All messages queued in the RTI that the joined federate will receive as RO messages%
 }
 \HLAFixedBlock{100.020}{665.822}{421.980}{\rmfamily\raggedright}{9.96}{12.00}{%
 ---%
 }
 \HLAFixedBlock{121.979}{665.822}{400.021}{\rmfamily\raggedright}{9.96}{12.00}{%
 All messages queued in the RTI that the joined federate will receive as TSO messages%
 }
\end{hlafixedpage}
