 a)%
 }
 \HLAFixedBlock{121.968}{658.800}{400.032}{\rmfamily\raggedright}{9.96}{12.00}{%
 If the requested lookahead is greater than or equal to the joined federate’s actual lookahead, the%
 }
 \HLAFixedBlock{121.979}{670.799}{400.021}{\rmfamily\raggedright}{9.96}{12.00}{%
 joined federate’s actual lookahead shall be set to the requested value.%
 }
 \HLAFixedBlock{100.019}{685.799}{421.981}{\rmfamily\raggedright}{9.96}{12.00}{%
 b)%
 }
 \HLAFixedBlock{121.941}{685.799}{400.059}{\rmfamily\raggedright}{9.96}{12.00}{%
 If the requested lookahead is less than the joined federate’s actual lookahead, the RTI shall be%
 }
 \HLAFixedBlock{121.979}{697.799}{400.021}{\rmfamily\raggedright}{9.96}{12.00}{%
 informed of the joined federate’s requested lookahead value.%
 }
