 \HLAFixedBlock{100.020}{526.800}{421.980}{\rmfamily\raggedright}{9.96}{12.00}{%
 a)%
 }
 \HLAFixedBlock{121.974}{526.800}{400.026}{\rmfamily\raggedright}{9.96}{12.00}{%
 The federate is connected to the RTI.%
 }
 \HLAFixedBlock{100.020}{539.820}{421.980}{\rmfamily\raggedright}{9.96}{12.00}{%
 b)%
 }
 \HLAFixedBlock{121.939}{539.820}{400.061}{\rmfamily\raggedright}{9.96}{12.00}{%
 The federation execution exists.%
 }
 \HLAFixedBlock{100.020}{552.780}{421.980}{\rmfamily\raggedright}{9.96}{12.00}{%
 c)%
 }
 \HLAFixedBlock{121.970}{552.780}{400.030}{\rmfamily\raggedright}{9.96}{12.00}{%
 The federate is joined to that federation execution. %
 }
 \HLAFixedBlock{100.020}{565.800}{421.980}{\rmfamily\raggedright}{9.96}{12.00}{%
 d)%
 }
 \HLAFixedBlock{121.979}{565.800}{400.021}{\rmfamily\raggedright}{9.96}{12.00}{%
 The joined federate is time-regulating.%
 }
 \HLAFixedBlock{100.020}{578.820}{421.980}{\rmfamily\raggedright}{9.96}{12.00}{%
 e)%
 }
 \HLAFixedBlock{121.981}{578.820}{400.019}{\rmfamily\raggedright}{9.96}{12.00}{%
 The joined federate has issued \emph{Update Attribute Values}, \emph{Send Interaction}, \emph{Send Interaction with}%
 }
 \HLAFixedBlock{121.979}{589.799}{400.021}{\rmfamily\raggedright}{9.96}{12.00}{%
 \emph{Regions}, or \emph{Delete Object Instance} service invocations previously and obtained the message%
 }
 \HLAFixedBlock{121.978}{600.779}{400.022}{\rmfamily\raggedright}{9.96}{12.00}{%
 retraction designator.%
 }
 \HLAFixedBlock{100.019}{613.799}{421.981}{\rmfamily\raggedright}{9.96}{12.00}{%
 f)%
 }
 \HLAFixedBlock{121.948}{613.799}{400.052}{\rmfamily\raggedright}{9.96}{12.00}{%
 If the joined federate is in the Time Granted state, the message associated with the specified%
 }
 \HLAFixedBlock{121.978}{624.779}{400.022}{\rmfamily\raggedright}{9.96}{12.00}{%
 retraction designator contained a timestamp that is larger than the joined federate’s current logical%
 }
 \HLAFixedBlock{121.978}{635.819}{400.022}{\rmfamily\raggedright}{9.96}{12.00}{%
 time plus its actual lookahead.%
 }
 \HLAFixedBlock{100.019}{648.779}{421.981}{\rmfamily\raggedright}{9.96}{12.00}{%
 g)%
 }
 \HLAFixedBlock{121.978}{648.779}{400.022}{\rmfamily\raggedright}{9.96}{12.00}{%
 If the joined federate is in the Time Advancing state, the message associated with the specified%
 }
 \HLAFixedBlock{121.978}{659.818}{400.022}{\rmfamily\raggedright}{9.96}{12.00}{%
 retraction designator contained a timestamp that is larger than the logical time specified in the joined%
 }
 \HLAFixedBlock{121.978}{670.798}{400.022}{\rmfamily\raggedright}{9.96}{12.00}{%
 federate’s most recent advance request plus its actual lookahead.%
 }
 \HLAFixedBlock{100.019}{683.818}{421.981}{\rmfamily\raggedright}{9.96}{12.00}{%
 h)%
 }
 \HLAFixedBlock{121.978}{683.818}{400.022}{\rmfamily\raggedright}{9.96}{12.00}{%
 Federate save not in progress.%
 }
 \HLAFixedBlock{100.019}{696.778}{421.981}{\rmfamily\raggedright}{9.96}{12.00}{%
 i)%
 }
 \HLAFixedBlock{121.980}{696.778}{400.020}{\rmfamily\raggedright}{9.96}{12.00}{%
 Federate restore not in progress.%
 }
\end{hlafixedpage}
