 \HLAServiceHeadingAt{219.383}{%
 \textbf{8.24 }\textbf{\emph{Change Attribute Order Type}}\textbf{ service}%
 }
 \HLAFixedBlock{90.000}{244.806}{432.000}{\rmfamily\raggedright}{9.96}{12.00}{%
 The preferred order type for each attribute of an object instance shall be initialized from the default attribute%
 }
 \HLAFixedBlock{90.000}{256.805}{432.000}{\rmfamily\raggedright}{9.96}{12.00}{%
 order type for its class in the creating federate. A joined federate may choose to change the preferred order%
 }
 \HLAFixedBlock{90.000}{268.805}{432.000}{\rmfamily\raggedright}{9.96}{12.00}{%
 type during execution. Invoking the \emph{Change Attribute Order Type} service shall change the order type for all%
 }
 \HLAFixedBlock{89.999}{280.805}{432.001}{\rmfamily\raggedright}{9.96}{12.00}{%
 future \emph{Update Attribute Values} service invocations for the specified instance attributes. When the ownership%
 }
 \HLAFixedBlock{90.000}{292.805}{432.000}{\rmfamily\raggedright}{9.96}{12.00}{%
 of an instance attribute is changed, the preferred order type shall be changed to the default attribute order%
 }
 \HLAFixedBlock{90.000}{304.805}{432.000}{\rmfamily\raggedright}{9.96}{12.00}{%
 type for its class in the newly owning federate.%
 }
