\thispagestyle{hla-body}
\begin{hlafixedpage}
 \HLAFixedBlock{121.980}{69.786}{482.020}{\rmfamily\raggedright}{9.96}{11.16}{%
 2)%
 }
 \HLAFixedBlock{142.025}{69.786}{461.975}{\rmfamily\raggedright}{9.96}{11.16}{%
 Parameters may be added to any MOM interaction class. Interactions of these classes that are%
 }
 \HLAFixedBlock{142.021}{81.785}{461.979}{\rmfamily\raggedright}{9.96}{11.16}{%
 sent by the RTI shall not contain the new parameters.%
 }
 \HLAFixedBlock{100.020}{96.785}{503.980}{\rmfamily\raggedright}{9.96}{11.16}{%
 b)%
 }
 \HLAFixedBlock{121.941}{96.785}{482.059}{\rmfamily\raggedright}{9.96}{11.16}{%
 Classes of interaction that the RTI shall receive (subclasses of HLAmanager.HLAfederate.HLA-%
 }
 \HLAFixedBlock{121.980}{108.785}{482.020}{\rmfamily\raggedright}{9.96}{11.16}{%
 adjust, %
 }
 \HLAFixedBlock{158.936}{108.785}{445.064}{\rmfamily\raggedright}{9.96}{11.16}{%
 HLAmanager.HLAfederate.HLArequest, %
 }
 \HLAFixedBlock{333.539}{108.785}{270.461}{\rmfamily\raggedright}{9.96}{11.16}{%
 HLAmanager.HLAfederate.HLAservice, %
 }
 \HLAFixedBlock{507.593}{108.785}{96.407}{\rmfamily\raggedright}{9.96}{11.16}{%
 and%
 }
