 }
 \HLAFixedBlock{90.000}{105.646}{514.000}{\rmfamily\raggedright}{9.96}{11.16}{%
 \textbf{11.5.2.1 Service report log format}%
 }
 \HLAFixedBlock{90.000}{129.785}{514.000}{\rmfamily\raggedright}{9.96}{11.16}{%
 The same JSON formatting used for service report parameters and arguments shall be used for service report%
 }
 \HLAFixedBlock{90.000}{141.785}{514.000}{\rmfamily\raggedright}{9.96}{11.16}{%
 log records. Each record shall be enclosed in a set of braces with no separator between records. The service%
 }
 \HLAFixedBlock{90.000}{153.784}{514.000}{\rmfamily\raggedright}{9.96}{11.16}{%
 report log file shall begin with an initial record containing information about the federate’s connection%
 }
 \HLAFixedBlock{90.000}{165.784}{514.000}{\rmfamily\raggedright}{9.96}{11.16}{%
 configuration, the joined federation’s HLAfederation object, and the joined federate's HLAfederate object%
 }
 \HLAFixedBlock{90.000}{177.784}{514.000}{\rmfamily\raggedright}{9.96}{11.16}{%
 (see ServiceReportInitialRecord in Table 5). The initial record shall be followed by one or more service%
 }
 \HLAFixedBlock{90.000}{189.784}{514.000}{\rmfamily\raggedright}{9.96}{11.16}{%
 report records (see ServiceReportRecord in Table 5).%
 }
\end{hlafixedpage}
