 \HLAFixedBlock{90.000}{69.786}{514.000}{\rmfamily\raggedright}{9.96}{11.16}{%
 Handles that are sent as part of MOM attribute value updates or as parameter values of MOM interactions%
 }
 \HLAFixedBlock{90.000}{81.785}{514.000}{\rmfamily\raggedright}{9.96}{11.16}{%
 are sent encoded and may be reconstituted in the manner described for each API.%
 }
 \HLAFixedBlock{90.000}{111.383}{514.000}{\rmfamily\raggedright}{10.98}{12.30}{%
 \textbf{12.3 Logical time, timestamps, and lookahead}%
 }
 \HLAFixedBlock{90.000}{136.806}{514.000}{\rmfamily\raggedright}{9.96}{11.16}{%
 In order to support customized implementations of logical time, timestamps, and lookahead, the C++ and%
 }
 \HLAFixedBlock{90.000}{148.806}{514.000}{\rmfamily\raggedright}{9.96}{11.16}{%
 Java %
 }
 \HLAFixedBlock{118.627}{148.806}{485.373}{\rmfamily\raggedright}{9.96}{11.16}{%
 APIs %
 }
 \HLAFixedBlock{152.542}{148.806}{451.458}{\rmfamily\raggedright}{9.96}{11.16}{%
 define %
 }
 \HLAFixedBlock{191.513}{148.806}{412.487}{\rmfamily\raggedright}{9.96}{11.16}{%
 a %
 }
 \HLAFixedBlock{209.932}{148.806}{394.068}{\rmfamily\raggedright}{9.96}{11.16}{%
 group %
 }
 \HLAFixedBlock{247.234}{148.806}{356.766}{\rmfamily\raggedright}{9.96}{11.16}{%
 of %
 }
 \HLAFixedBlock{269.484}{148.806}{334.516}{\rmfamily\raggedright}{9.96}{11.16}{%
