 \HLAFixedBlock{90.001}{333.782}{513.999}{\rmfamily\raggedright}{9.96}{11.16}{%
 exception of the following HLA services related to callbacks, since the protocol allows for two-way%
 }
 \HLAFixedBlock{90.001}{345.781}{513.999}{\rmfamily\raggedright}{9.96}{11.16}{%
