 \HLAFixedBlock{121.981}{453.780}{482.019}{\rmfamily\raggedright}{9.96}{11.16}{%
 Callback Model%
 }
 \HLAFixedBlock{90.001}{477.640}{513.999}{\rmfamily\raggedright}{9.96}{11.16}{%
 \textbf{12.13.3.3 HLA Service Arguments}%
 }
 \HLAFixedBlock{90.001}{501.779}{513.999}{\rmfamily\raggedright}{9.96}{11.16}{%
 The following apply to HLA service arguments when invoked over the federate protocol:%
 }
 \HLAFixedBlock{100.021}{525.778}{503.979}{\rmfamily\raggedright}{9.96}{11.16}{%
 a)%
 }
 \HLAFixedBlock{121.981}{525.778}{482.019}{\rmfamily\raggedright}{9.96}{11.16}{%
 \textbf{FOM Modules}%
 }
 \HLAFixedBlock{186.840}{525.778}{417.160}{\rmfamily\raggedright}{9.96}{11.16}{%
 : Service arguments indicating FOM modules shall be specified in one of the%
 }
 \HLAFixedBlock{121.981}{537.778}{482.019}{\rmfamily\raggedright}{9.96}{11.16}{%
 following three ways:%
 }
 \HLAFixedBlock{121.981}{549.778}{482.019}{\rmfamily\raggedright}{9.96}{11.16}{%
 1)%
 }
 \HLAFixedBlock{142.025}{549.778}{461.975}{\rmfamily\raggedright}{9.96}{11.16}{%
 Using a URL indicating the location of the FOM module;%
 }
 \HLAFixedBlock{121.981}{561.778}{482.019}{\rmfamily\raggedright}{9.96}{11.16}{%
 2)%
 }
 \HLAFixedBlock{142.026}{561.778}{461.974}{\rmfamily\raggedright}{9.96}{11.16}{%
 By providing the full FOM module content;%
 }
 \HLAFixedBlock{121.981}{573.778}{482.019}{\rmfamily\raggedright}{9.96}{11.16}{%
 3)%
 }
 \HLAFixedBlock{142.026}{573.778}{461.974}{\rmfamily\raggedright}{9.96}{11.16}{%
 By providing a compressed FOM module using ZIP (ISO/IEC 21320-1:2015) compression.%
 }
 \HLAFixedBlock{100.021}{585.777}{503.979}{\rmfamily\raggedright}{9.96}{11.16}{%
 b)%
 }
 \HLAFixedBlock{121.981}{585.777}{482.019}{\rmfamily\raggedright}{9.96}{11.16}{%
 \textbf{Time Representation}%
 }
 \HLAFixedBlock{211.201}{585.777}{392.799}{\rmfamily\raggedright}{9.96}{11.16}{%
 : Arguments indicating Time Representation shall be specified using the name%
 }
 \HLAFixedBlock{121.981}{597.777}{482.019}{\rmfamily\raggedright}{9.96}{11.16}{%
 of the HLA time type, for example HLAinteger64Time.%
 }
 \HLAFixedBlock{100.021}{609.777}{503.979}{\rmfamily\raggedright}{9.96}{11.16}{%
 c)%
 }
 \HLAFixedBlock{121.981}{609.777}{482.019}{\rmfamily\raggedright}{9.96}{11.16}{%
 \textbf{Handles as arguments}%
 }
 \HLAFixedBlock{216.781}{609.777}{387.219}{\rmfamily\raggedright}{9.96}{11.16}{%
 : All handle arguments shall be the series of opaque encoded bytes resulting%
 }
 \HLAFixedBlock{121.981}{621.777}{482.019}{\rmfamily\raggedright}{9.96}{11.16}{%
 from the handle's "encode" operation (see 12.11.6.4 and 12.12.6.4) with the following exception:%
 }
 \HLAFixedBlock{121.981}{633.777}{482.019}{\rmfamily\raggedright}{9.96}{11.16}{%
 1)%
 }
 \HLAFixedBlock{142.024}{633.777}{461.976}{\rmfamily\raggedright}{9.96}{11.16}{%
 Conveyed Regions: Conveyed Regions shall not be passed as handles but shall be passed as a%
