 \HLAFixedBlock{100.020}{669.776}{503.980}{\rmfamily\raggedright}{9.96}{11.16}{%
 d)%
 }
 \HLAFixedBlock{121.980}{669.776}{482.020}{\rmfamily\raggedright}{9.96}{11.16}{%
 \textbf{Handles as values:}%
 }
 \HLAFixedBlock{201.779}{669.776}{402.221}{\rmfamily\raggedright}{9.96}{11.16}{%
 When receiving a handle as part of a value in an attribute or parameter handle%
 }
 \HLAFixedBlock{121.980}{681.776}{482.020}{\rmfamily\raggedright}{9.96}{11.16}{%
 value map, the handle shall be just the series of opaque encoded bytes as stated in c) .%
