 \HLAFixedBlock{121.980}{693.776}{482.020}{\rmfamily\raggedright}{9.96}{11.16}{%
 \textbf{Names, labels and strings}%
 }
 \HLAFixedBlock{230.700}{693.776}{373.300}{\rmfamily\raggedright}{9.96}{11.16}{%
 : The names, labels, and strings described in Clause 4 through Clause 10%
 }
 \HLAFixedBlock{121.980}{705.775}{482.020}{\rmfamily\raggedright}{9.96}{11.16}{%
 of this specification shall be mapped to native strings according to the encoding in Annex D.%
 }
