\HLASourcePage{412}{411}
\HLAServiceBookmark{12.13.5}{2}{Transport Layer}
\thispagestyle{hla-body}
\begin{hlafixedpage}
 \HLAFixedBlock{90.000}{69.786}{514.000}{\rmfamily\raggedright}{9.96}{11.16}{%
 Figure 32 illustrates how a session is resumed for the RTI.%
 }
 \HLAFixedBlock{90.000}{281.765}{514.000}{\rmfamily\raggedright}{9.96}{11.16}{%
 Figure 33 illustrates the exception states for the RTI.%
 }
 \HLAFixedBlock{90.000}{524.686}{514.000}{\rmfamily\raggedright}{9.96}{11.16}{%
 \textbf{12.13.5 Transport Layer}%
 }
 \HLAFixedBlock{90.000}{548.825}{514.000}{\rmfamily\raggedright}{9.96}{11.16}{%
 The following rules shall apply to the transport layer. %
 }
 \HLAFixedBlock{100.020}{572.824}{503.980}{\rmfamily\raggedright}{9.96}{11.16}{%
 ---%
 }
 \HLAFixedBlock{121.980}{572.824}{482.020}{\rmfamily\raggedright}{9.96}{11.16}{%
 The following transport protocols shall be supported:%
 }
 \HLAFixedBlock{142.020}{584.824}{461.980}{\rmfamily\raggedright}{9.96}{11.16}{%
 ---Transmission Control Protocol/Internet Protocol (TCP/IP),%
 }
 \HLAFixedBlock{142.020}{596.824}{461.980}{\rmfamily\raggedright}{9.96}{11.16}{%
 ---Transport Layer Security (TLS) 1.3 [B7] on top of TCP/IP for encrypted communication,%
 }
 \HLAFixedBlock{142.020}{608.824}{461.980}{\rmfamily\raggedright}{9.96}{11.16}{%
 ---WebSocket [B17] on top of TCP/IP,%
 }
 \HLAFixedBlock{142.020}{620.824}{461.980}{\rmfamily\raggedright}{9.96}{11.16}{%
 ---Secure WebSocket on top of TLS 1.3 for encrypted communication.%
 }
 \HLAFixedBlock{100.020}{632.823}{503.980}{\rmfamily\raggedright}{9.96}{11.16}{%
 ---%
 }
 \HLAFixedBlock{121.980}{632.823}{482.020}{\rmfamily\raggedright}{9.96}{11.16}{%
 The RTI shall be available at one or more addresses, specified using either IP address or DNS name,%
 }
 \HLAFixedBlock{121.981}{644.823}{482.019}{\rmfamily\raggedright}{9.96}{11.16}{%
 together with a port number%
 }
 \HLAFixedBlock{142.020}{656.823}{461.980}{\rmfamily\raggedright}{9.96}{11.16}{%
 ---The default port number for TCP is 15164, for TLS 1.3 is 15165, for WebSocket it is 80 and%
 }
 \HLAFixedBlock{142.020}{668.823}{461.980}{\rmfamily\raggedright}{9.96}{11.16}{%
 for Secure WebSocket it is 443.%
 }
 \HLAFixedBlock{142.020}{680.823}{461.980}{\rmfamily\raggedright}{9.96}{11.16}{%
 ---The RID shall support alternative configuration of the address and port.%
 }
 \HLAFixedBlock{226.980}{241.666}{377.020}{\rmfamily\raggedright}{9.96}{11.16}{%
 \textbf{Figure 32---RTI Resume State Diagram}%
 }
 \HLAFixedBlock{195.540}{490.006}{408.460}{\rmfamily\raggedright}{9.96}{11.16}{%
 \textbf{Figure 33---RTI Exception Handling State Diagram}%
 }
\end{hlafixedpage}
\clearpage

\HLASourcePage{413}{412}
\HLAServiceBookmark{12.13.5.1}{3}{Special consideration for TLS 1.3}
\HLAServiceBookmark{12.13.5.2}{3}{Special considerations for WebSockets}
\thispagestyle{hla-body}
\begin{hlafixedpage}
 \HLAFixedBlock{100.020}{69.786}{503.980}{\rmfamily\raggedright}{9.96}{11.16}{%
 ---%
 }
 \HLAFixedBlock{121.980}{69.786}{482.020}{\rmfamily\raggedright}{9.96}{11.16}{%
 One transport layer connection shall support exactly one federate session.%
 }
 \HLAFixedBlock{100.020}{81.785}{503.980}{\rmfamily\raggedright}{9.96}{11.16}{%
 ---%
 }
 \HLAFixedBlock{121.980}{81.785}{482.020}{\rmfamily\raggedright}{9.96}{11.16}{%
 The federate shall initiate a connection. %
 }
 \HLAFixedBlock{100.020}{93.785}{503.980}{\rmfamily\raggedright}{9.96}{11.16}{%
 ---%
 }
 \HLAFixedBlock{121.980}{93.785}{482.020}{\rmfamily\raggedright}{9.96}{11.16}{%
 The federate and the RTI shall be able to send messages simultaneously.%
 }
 \HLAFixedBlock{100.020}{105.785}{503.980}{\rmfamily\raggedright}{9.96}{11.16}{%
 ---%
 }
 \HLAFixedBlock{121.980}{105.785}{482.020}{\rmfamily\raggedright}{9.96}{11.16}{%
 The federate shall terminate the connection.%
 }
 \HLAFixedBlock{100.020}{117.785}{503.980}{\rmfamily\raggedright}{9.96}{11.16}{%
 ---%
 }
 \HLAFixedBlock{121.980}{117.785}{482.020}{\rmfamily\raggedright}{9.96}{11.16}{%
 If a connection fault occurs, either the federate or the RTI may terminate the connection.%
 }
 \HLAFixedBlock{100.019}{129.785}{503.981}{\rmfamily\raggedright}{9.96}{11.16}{%
 ---%
 }
 \HLAFixedBlock{121.979}{129.785}{482.021}{\rmfamily\raggedright}{9.96}{11.16}{%
 If a connection fault occurs, the federate may initiate a new connection to resume the existing%
 }
 \HLAFixedBlock{121.980}{141.785}{482.020}{\rmfamily\raggedright}{9.96}{11.16}{%
 federate session.%
 }
 \HLAFixedBlock{90.000}{165.645}{514.000}{\rmfamily\raggedright}{9.96}{11.16}{%
 \textbf{12.13.5.1 Special consideration for TLS 1.3 }%
 }
 \HLAFixedBlock{90.000}{189.784}{514.000}{\rmfamily\raggedright}{9.96}{11.16}{%
 An RTI and a federate may optionally support TLS 1.3 transportation. When using TLS 1.3 the following%
 }
 \HLAFixedBlock{90.000}{201.784}{514.000}{\rmfamily\raggedright}{9.96}{11.16}{%
 modes shall be supported by the RTI and the Federate:%
 }
 \HLAFixedBlock{100.020}{225.783}{503.980}{\rmfamily\raggedright}{9.96}{11.16}{%
 a)%
 }
 \HLAFixedBlock{121.975}{225.783}{482.025}{\rmfamily\raggedright}{9.96}{11.16}{%
 No certificate validation, i.e. encryption only.%
 }
 \HLAFixedBlock{100.020}{237.783}{503.980}{\rmfamily\raggedright}{9.96}{11.16}{%
 b)%
 }
 \HLAFixedBlock{121.942}{237.783}{482.058}{\rmfamily\raggedright}{9.96}{11.16}{%
 Server (RTI) certificate validation. In this case a server certificate and a corresponding private key%
 }
 \HLAFixedBlock{121.980}{249.783}{482.020}{\rmfamily\raggedright}{9.96}{11.16}{%
 shall be installed at the RTI. The federate shall verify the validity of the server certificate and the%
 }
 \HLAFixedBlock{121.980}{261.783}{482.020}{\rmfamily\raggedright}{9.96}{11.16}{%
 identity of the RTI using a trusted certificate. %
 }
 \HLAFixedBlock{89.999}{285.643}{514.001}{\rmfamily\raggedright}{9.96}{11.16}{%
 \textbf{12.13.5.2 Special considerations for WebSockets}%
 }
 \HLAFixedBlock{89.999}{309.782}{514.001}{\rmfamily\raggedright}{9.96}{11.16}{%
 The following applies to both the RTI and the Federate:%
 }
 \HLAFixedBlock{100.019}{333.781}{503.981}{\rmfamily\raggedright}{9.96}{11.16}{%
 a)%
 }
 \HLAFixedBlock{121.981}{333.781}{482.019}{\rmfamily\raggedright}{9.96}{11.16}{%
 Only binary data frames shall be used. Text data frames are not allowed.%
 }
 \HLAFixedBlock{100.019}{345.781}{503.981}{\rmfamily\raggedright}{9.96}{11.16}{%
 b)%
 }
 \HLAFixedBlock{121.959}{345.781}{482.041}{\rmfamily\raggedright}{9.96}{11.16}{%
 The modes defined for TLS 1.3 in 12.13.5.1 also apply for Secure WebSocket.%
 }
 \HLAFixedBlock{100.019}{357.781}{503.981}{\rmfamily\raggedright}{9.96}{11.16}{%
 c)%
 }
 \HLAFixedBlock{121.965}{357.781}{482.035}{\rmfamily\raggedright}{9.96}{11.16}{%
 No WebSocket subprotocol or extension should be used.%
 }
 \HLAFixedBlock{100.019}{369.781}{503.981}{\rmfamily\raggedright}{9.96}{11.16}{%
 d)%
 }
 \HLAFixedBlock{121.960}{369.781}{482.040}{\rmfamily\raggedright}{9.96}{11.16}{%
 No WebSocket ping messages should be used.%
 }
\end{hlafixedpage}
\clearpage

\HLASourcePage{414}{413}
\HLAServiceBookmark{13.1}{1}{Federate conformance}
\HLAServiceBookmark{13.2}{1}{RTI conformance}
\thispagestyle{hla-body}
\begin{hlafixedpage}
 \HLAFixedBlock{90.000}{69.120}{514.000}{\rmfamily\raggedright}{12.00}{13.44}{%
 \textbf{13. Conformance}%
 }
 \HLAFixedBlock{90.000}{95.766}{514.000}{\rmfamily\raggedright}{9.96}{11.16}{%
 The interface defined in this document between a federate and an RTI places requirements on both sides of%
 }
 \HLAFixedBlock{90.000}{107.765}{514.000}{\rmfamily\raggedright}{9.96}{11.16}{%
 the interface. This clause defines the measures for assessment of federates and RTIs, based upon the%
 }
 \HLAFixedBlock{89.999}{119.765}{514.001}{\rmfamily\raggedright}{9.96}{11.16}{%
 normative clauses of this specification. Because a large number of federates rely on a relatively much%
 }
 \HLAFixedBlock{89.999}{131.765}{514.001}{\rmfamily\raggedright}{9.96}{11.16}{%
 smaller number of RTIs, the measures are much more strict for RTIs. Within the HLA community,%
 }
 \HLAFixedBlock{89.999}{143.765}{514.001}{\rmfamily\raggedright}{9.96}{11.16}{%
 verification capabilities will conduct these assessments experimentally and publicly certify the results. Only%
 }
 \HLAFixedBlock{89.999}{155.765}{514.001}{\rmfamily\raggedright}{9.96}{11.16}{%
 when results certified by a recognized authority are publicly available shall the label “HLA Conforming” be%
 }
 \HLAFixedBlock{89.999}{167.765}{514.001}{\rmfamily\raggedright}{9.96}{11.16}{%
 used.%
 }
 \HLAFixedBlock{90.000}{197.363}{514.000}{\rmfamily\raggedright}{10.98}{12.30}{%
 \textbf{13.1 Federate conformance}%
 }
 \HLAFixedBlock{90.000}{222.786}{514.000}{\rmfamily\raggedright}{9.96}{11.16}{%
 An HLA-conforming federate shall document the elements of the interface defined in this document that are%
 }
 \HLAFixedBlock{90.000}{234.785}{514.000}{\rmfamily\raggedright}{9.96}{11.16}{%
 used in the conformance table of its SOM as specified in IEEE Std 1516.2-2025.%
 }
 \HLAFixedBlock{90.000}{264.383}{514.000}{\rmfamily\raggedright}{10.98}{12.30}{%
 \textbf{13.2 RTI conformance}%
 }
 \HLAFixedBlock{90.000}{289.806}{514.000}{\rmfamily\raggedright}{9.96}{11.16}{%
 An HLA-conforming RTI shall implement all the joined federate-initiated services and invoke all the RTI-%
 }
 \HLAFixedBlock{90.000}{301.805}{514.000}{\rmfamily\raggedright}{9.96}{11.16}{%
 initiated services as defined in this document. Mapping these interfaces to programming languages shall be%
 }
 \HLAFixedBlock{90.000}{313.805}{514.000}{\rmfamily\raggedright}{9.96}{11.16}{%
 done in accordance with Clause 12, and at least one language-specific API shall be implemented.%
 }
 \HLAFixedBlock{90.000}{325.805}{514.000}{\rmfamily\raggedright}{9.96}{11.16}{%
 Conformance verification shall be done according to the language API(s) implemented, and certified results%
 }
 \HLAFixedBlock{90.000}{337.805}{514.000}{\rmfamily\raggedright}{9.96}{11.16}{%
 shall reflect the language API(s) verified.%
 }
\end{hlafixedpage}
\clearpage

\HLASourcePage{415}{414}
\thispagestyle{hla-body}
\begin{hlafixedpage}
 \HLAFixedBlock{90.000}{68.648}{514.000}{\rmfamily\raggedright}{13.98}{15.66}{%
 \textbf{Annex A}%
 }
 \HLAFixedBlock{90.000}{97.140}{514.000}{\rmfamily\raggedright}{12.00}{13.44}{%
 (informative) %
 }
 \HLAFixedBlock{90.000}{128.648}{514.000}{\rmfamily\raggedright}{13.98}{15.66}{%
 \textbf{API information}%
 }
 \HLAFixedBlock{90.000}{157.806}{514.000}{\rmfamily\raggedright}{9.96}{11.16}{%
 C++ and Java are such common programming languages that this standard dictates a language binding for%
 }
 \HLAFixedBlock{90.000}{169.805}{514.000}{\rmfamily\raggedright}{9.96}{11.16}{%
 each API (see Annex B and Annex C) that must be used in order to comply with this standard. The same%
 }
 \HLAFixedBlock{90.000}{181.805}{514.000}{\rmfamily\raggedright}{9.96}{11.16}{%
 applies to the Federate Protocol API (see Annex E). However, for other languages, e.g., Ada 95, C\#, Python,%
 }
 \HLAFixedBlock{90.000}{193.805}{514.000}{\rmfamily\raggedright}{9.96}{11.16}{%
 it is still possible to develop RTI APIs that may be considered compliant. It is up to the implementer of the%
 }
 \HLAFixedBlock{90.000}{205.805}{514.000}{\rmfamily\raggedright}{9.96}{11.16}{%
 particular API to determine how to map the body of this standard to the respective programming language.%
 }
\end{hlafixedpage}
\clearpage

