 \HLAFixedBlock{90.000}{128.648}{514.000}{\rmfamily\raggedright}{13.98}{15.66}{%
 \textbf{FOM Document Data (FDD) XML Schema declaration}%
 }
 \HLAFixedBlock{90.000}{157.806}{514.000}{\rmfamily\raggedright}{9.96}{11.16}{%
 The XML specification defines two levels of correctness for XML documents: well-formed and valid. A%
 }
 \HLAFixedBlock{90.000}{169.805}{514.000}{\rmfamily\raggedright}{9.96}{11.16}{%
 well-formed XML document is one that follows the syntax constraints of XML; for example, all element%
 }
 \HLAFixedBlock{90.000}{181.805}{514.000}{\rmfamily\raggedright}{9.96}{11.16}{%
 opening and closing tags are appropriately nested. A valid XML file is one that is well formed and complies%
 }
 \HLAFixedBlock{90.000}{193.805}{514.000}{\rmfamily\raggedright}{9.96}{11.16}{%
 with an XML Schema. %
 }
 \HLAFixedBlock{90.000}{217.805}{514.000}{\rmfamily\raggedright}{9.96}{11.16}{%
 The XML Schema declaration for the FDD shall be defined in the file named IEEE1516-FDD-2025.xsd.%
 }
 \HLAFixedBlock{90.000}{229.805}{514.000}{\rmfamily\raggedright}{9.96}{11.16}{%
 This file is part of this specification and can be downloaded from either of the following locations: %
 }
 \HLAFixedBlock{100.020}{253.804}{503.980}{\rmfamily\raggedright}{9.96}{11.16}{%
 ---%
 }
 \HLAFixedBlock{120.000}{253.804}{484.000}{\rmfamily\raggedright}{9.96}{11.16}{%
 http://standards.ieee.org/downloads/1516/1516.1-2025/IEEE1516-2025\_XML.zip %
 }
 \HLAFixedBlock{100.020}{265.806}{503.980}{\rmfamily\raggedright}{9.96}{11.16}{%
 ---%
 }
 \HLAFixedBlock{120.000}{265.806}{484.000}{\rmfamily\raggedright}{9.96}{11.16}{%
 http://www.sisostds.org/schemas.aspx/IEEE1516-2025\_XML.zip%
 }
 \HLAFixedBlock{90.000}{289.806}{514.000}{\rmfamily\raggedright}{9.96}{11.16}{%
 An FDD shall be considered valid if and only if it complies with the FDD XML Schema. All compliant RTI%
 }
 \HLAFixedBlock{90.000}{301.805}{514.000}{\rmfamily\raggedright}{9.96}{11.16}{%
 implementations shall be able to read valid FDDs. %
 }
 \HLAFixedBlock{90.000}{325.805}{514.000}{\rmfamily\raggedright}{9.96}{11.16}{%
 The FDD Schema represents the minimum set of FOM information required to initialize a federation. The%
 }
 \HLAFixedBlock{90.000}{337.805}{514.000}{\rmfamily\raggedright}{9.96}{11.16}{%
 Schema allows additional FOM information to be present in the FDD. Furthermore, the schema allows the%
 }
 \HLAFixedBlock{90.000}{349.805}{514.000}{\rmfamily\raggedright}{9.96}{11.16}{%
 FDD to contain additional non-FOM elements and attributes, e.g., RTI specific information.%
 }
\end{hlafixedpage}
